const key = new PluginKey<DecorationSet>("inFlowAnchor");

/** Ephemeral underline on the passage a tool is about; never a saved mark. */
export const InFlowAnchor = Extension.create({
  name: "inFlowAnchor",
  addProseMirrorPlugins() {
    return [
      new Plugin<DecorationSet>({
        key,
        state: {
          init: () => DecorationSet.empty,
          apply: (tr, previous) =>
            tr.getMeta(key) ?? previous.map(tr.mapping, tr.doc),
        },
        props: { decorations: (state) => key.getState(state) },
      }),
    ];
  },
});

const PAUSE_MS = 1200;
const STALL_CHECK_MS = 42_000;
const MAX_TRACKED = 200;
const QUIET_AFTER_NO_MS = 2 * 60_000;

let snapshot: InFlowSnapshot = { active: null, ticks: [] };
let controller: InFlowController | null = null;

export const inFlowSnapshot = () => snapshot;
export const inFlowController = () => controller;

function publish(next: InFlowSnapshot) {
  snapshot = next;
  window.dispatchEvent(
    new CustomEvent<InFlowSnapshot>(IN_FLOW_EVENT, { detail: next }),
  );
}

export interface InFlowController {
  applyVariant(text: string): void;
  selectSentence(index: number): void;
  highlightSentence(index: number | null): void;
  dismiss(): void;
  keep(name: string, config: SavedTool["config"]): Promise<void>;
  research(claim: string): Promise<string | null>;
  jot(text: string): Promise<boolean>;
  openSaved(tool: SavedTool): void;
  openKind(kind: ToolKind, passage?: string): void;
  focusAnchor(): void;
  /** Rhythm Strip: move the comfortable band; kept if the writer keeps the tool. */
  setRhythmBand(min: number, max: number): void;
  /** Re-run Reader Questions for a different imagined reader. */
  reask(angle: string): void;
  /** Viewport rect of the active tool's passage (its sentence, when it has one). */
  anchorRect(): DOMRect | null;
  /** Viewport top of the paragraph at `pos`, for margin ticks. */
  blockTop(pos: number): number | null;
}

/** Document position of a character offset inside a paragraph's text. */
function posAtOffset(node: PmNode, blockPos: number, offset: number): number {
  let seen = 0;
  let result = blockPos + node.nodeSize - 1;
  let found = false;
  node.forEach((child, childOffset) => {
    if (found) return;
    const length = child.isText ? child.text!.length : 0;
    if (child.isText && offset <= seen + length) {
      result = blockPos + 1 + childOffset + (offset - seen);
      found = true;
      return;
    }
    seen += length;
  });
  return result;
}

function isTrackedBlock(node: PmNode | null | undefined): node is PmNode {
  return !!node && node.type.name === "paragraph";
}

export function startInFlowTools(
  editor: Editor,
  options: {
    getClient: () => ConvexClient | null | undefined;
    folioId: string;
    brief: ProjectBrief | null;
    openPanel?: (panel: "citations") => void;
  },
): () => void {
  const { folioId, brief } = options;
  let activities = new Map<number, BlockActivity>();
  let dirty = new Set<number>();
  let pauseTimer: ReturnType<typeof setTimeout> | undefined;
  let stallTimer: ReturnType<typeof setTimeout> | undefined;
  let publishTimer: ReturnType<typeof setTimeout> | undefined;
  let enabled = false;
  let stopped = false;
  let running = false;
  let generation = 0;
  let active: ActiveTool | null = null;
  let highlight: number | null = null;

  const setActive = (next: ActiveTool | null) => {
    active = next;
    // Often called from inside a transaction listener; never dispatch nested.
    queueMicrotask(drawAnchor);
    publish({ active, ticks: ticks() });
  };

  const ticks = (): number[] => {
    const now = Date.now();
    const out: number[] = [];
    for (const [pos, activity] of activities) {
      if (readStruggle(activity, now).score >= 0.35) out.push(pos);
    }
    return out.slice(0, 40);
  };

  const drawAnchor = () => {
    if (stopped || editor.isDestroyed) return;
    const decorations: Decoration[] = [];
    if (active) {
      const node = editor.state.doc.nodeAt(active.from);
      if (isTrackedBlock(node)) {
        const from = active.sentenceFrom ?? active.from + 1;
        const to = active.sentenceTo ?? active.to - 1;
        if (to > from)
          decorations.push(
            Decoration.inline(from, to, {
              class: "twyne-in-flow-span",
              "data-in-flow-tool": active.kind,
            }),
          );
        if (highlight !== null) {
          const s = splitSentences(node.textContent)[highlight];
          if (s)
            decorations.push(
              Decoration.inline(
                posAtOffset(node, active.from, s.from),
                posAtOffset(node, active.from, s.to),
                { class: "twyne-in-flow-sentence" },
              ),
            );
        }
      }
    }
    editor.view.dispatch(
      editor.state.tr
        .setMeta(key, DecorationSet.create(editor.state.doc, decorations))
        .setMeta("addToHistory", false),
    );
  };

  /* ── Tracking ─────────────────────────────────────────────────── */

  const onTransaction = ({ transaction: tr }: { transaction: Transaction }) => {
    if (stopped || !tr.docChanged) return;
    // Programmatic writes (loads, our own decorations, remote mirrors) mark
    // themselves out of history; they are not the writer's effort.
    const undo = isHistoryTransaction(tr);
    const counted = undo || tr.getMeta("addToHistory") !== false;
    const now = Date.now();

    const remapped = new Map<number, BlockActivity>();
    for (const [pos, activity] of activities) {
      const mapped = tr.mapping.mapResult(pos, 1);
      if (!mapped.deleted && isTrackedBlock(tr.doc.nodeAt(mapped.pos)))
        remapped.set(mapped.pos, activity);
    }
    activities = remapped;
    dirty = new Set(
      [...dirty]
        .map((pos) => tr.mapping.map(pos, 1))
        .filter((pos) => activities.has(pos)),
    );

    if (active) {
      const from = tr.mapping.mapResult(active.from, 1);
      if (from.deleted || !isTrackedBlock(tr.doc.nodeAt(from.pos))) {
        setActive(null);
      } else {
        const node = tr.doc.nodeAt(from.pos)!;
        active = {
          ...active,
          from: from.pos,
          to: from.pos + node.nodeSize,
          sentenceFrom:
            active.sentenceFrom === undefined
              ? undefined
              : tr.mapping.map(active.sentenceFrom, -1),
          sentenceTo:
            active.sentenceTo === undefined
              ? undefined
              : tr.mapping.map(active.sentenceTo, 1),
        };
        clearTimeout(publishTimer);
        publishTimer = setTimeout(() => {
          // Rhythm is arithmetic on the writer's own sentences: keep it live.
          if (active?.kind === "rhythm-strip") {
            const element = active.spec.elements.tool;
            const block = editor.state.doc.nodeAt(active.from);
            if (element.type === "RhythmStrip" && isTrackedBlock(block)) {
              active = {
                ...active,
                spec: seedSpec("rhythm-strip", block.textContent, {
                  config:…1696 tokens truncated…ckPos + node.nodeSize,
      sentenceFrom,
      sentenceTo,
      reason: opts.reason,
      spec,
      status: "filling",
      tentative: opts.tentative ?? false,
      savedId: opts.saved?.id,
    };
    highlight = null;
    setActive(tool);
    void fill(tool, passage, blockPos);
  };

  const fill = async (tool: ActiveTool, passage: string, blockPos: number) => {
    const [settings, modelBrief] = await Promise.all([
      loadAiSettingsFromIdb(),
      loadModelBriefForFolio(folioId, brief),
    ]);
    if (stopped || editor.isDestroyed || active?.id !== tool.id) return;
    const generate =
      settings && hasConfiguredAiProvider(settings)
        ? (request: Parameters<typeof runClientInFlowTool>[0]) =>
            runClientInFlowTool(request, settings)
        : null;
    const stillThis = () => !stopped && active?.id === tool.id;
    const result = await fillSpec(
      tool.spec,
      {
        passage,
        preceding: editor.state.doc.textBetween(
          Math.max(0, blockPos - 3000),
          Math.min(blockPos, editor.state.doc.content.size),
          "\n",
        ),
        goal: [modelBrief?.answers.goal, modelBrief?.answers.constraints]
          .filter(Boolean)
          .join("\n"),
        audience: modelBrief?.answers.audience ?? "",
      },
      generate,
      (spec) => {
        if (stillThis()) setActive({ ...active!, spec });
      },
    );
    if (stillThis())
      setActive({
        ...active!,
        spec: result.spec,
        status: "ready",
        notice: result.notice,
      });
  };

  /* ── Controller ───────────────────────────────────────────────── */

  const quiet = (pos: number) => {
    const activity = activities.get(pos);
    if (activity) activities.set(pos, coolDown(activity, Date.now()));
  };

  controller = {
    applyVariant(text) {
      if (!active || editor.isDestroyed) return;
      const node = editor.state.doc.nodeAt(active.from);
      if (!isTrackedBlock(node)) return;
      const element = active.spec.elements.tool;
      if (element.type !== "SentenceLab") return;
      let from = active.sentenceFrom;
      let to = active.sentenceTo;
      const current =
        from !== undefined && to !== undefined
          ? editor.state.doc.textBetween(from, to)
          : "";
      if (current !== element.props.sentence) {
        // The sentence moved or changed since the tool opened; find it again.
        const span = splitSentences(node.textContent).find(
          (s) => s.text === element.props.sentence,
        );
        if (!span) {
          setActive({
            ...active,
            notice: "That sentence has changed since the tool opened.",
          });
          return;
        }
        from = posAtOffset(node, active.from, span.from);
        to = posAtOffset(node, active.from, span.to);
      }
      const pos = active.from;
      editor
        .chain()
        .focus()
        .insertContentAt({ from: from!, to: to! }, text)
        .run();
      quiet(pos);
      setActive(null);
    },
    selectSentence(index) {
      if (!active) return;
      const node = editor.state.doc.nodeAt(active.from);
      if (!isTrackedBlock(node)) return;
      const s = splitSentences(node.textContent)[index];
      if (!s) return;
      editor
        .chain()
        .focus()
        .setTextSelection({
          from: posAtOffset(node, active.from, s.from),
          to: posAtOffset(node, active.from, s.to),
        })
        .scrollIntoView()
        .run();
    },
    highlightSentence(index) {
      highlight = index;
      queueMicrotask(drawAnchor);
    },
    dismiss() {
      if (active) quiet(active.from);
      highlight = null;
      setActive(null);
    },
    async keep(name, config) {
      if (!active) return;
      const saved = await saveTool({ kind: active.kind, name, config });
      if (active)
        setActive({
          ...active,
          savedId: saved.id,
          notice: "Kept in Your tools.",
        });
    },
    async research(claim) {
      options.openPanel?.("citations");
      const result = await researchSelection({ anchor: claim, folioId });
      return result.ok
        ? null
        : (result.message ?? "The Apparatus could not start.");
    },
    async jot(text) {
      try {
        const notebook = await loadWritingToolsNotebook(folioId);
        notebook.scraps = [
          ...notebook.scraps,
          { id: `scrap-${Date.now().toString(36)}`, text },
        ];
        await saveWritingToolsNotebook(folioId, notebook);
        return true;
      } catch {
        return false;
      }
    },
    openSaved(tool) {
      const block = cursorBlock();
      if (!block) return;
      open(tool.kind, block.pos, {
        activity: activities.get(block.pos),
        reason: `From Your tools: ${tool.name}.`,
        saved: tool,
      });
    },
    openKind(kind, passage) {
      let pos: number | null = null;
      const needle = passage?.trim().slice(0, 120);
      if (needle) {
        editor.state.doc.descendants((node, nodePos) => {
          if (pos !== null) return false;
          if (isTrackedBlock(node) && node.textContent.includes(needle)) {
            pos = nodePos;
            return false;
          }
          return true;
        });
      }
      pos ??= cursorBlock()?.pos ?? null;
      if (pos === null) {
        // No cursor in a paragraph: the longest paragraph is the best guess.
        let longest = -1;
        editor.state.doc.descendants((node, nodePos) => {
          if (isTrackedBlock(node) && node.textContent.length > longest) {
            longest = node.textContent.length;
            pos = nodePos;
          }
          return !isTrackedBlock(node);
        });
      }
      if (pos === null) return;
      open(kind, pos, {
        activity: activities.get(pos),
        reason: "Opened from the rubric.",
      });
      editor
        .chain()
        .setTextSelection(pos + 1)
        .scrollIntoView()
        .run();
    },
    setRhythmBand(min, max) {
      if (!active || active.kind !== "rhythm-strip") return;
      const block = editor.state.doc.nodeAt(active.from);
      if (!isTrackedBlock(block)) return;
      const targetMin = Math.max(1, Math.min(80, Math.round(min)));
      setActive({
        ...active,
        spec: seedSpec("rhythm-strip", block.textContent, {
          config: {
            targetMin,
            targetMax: Math.max(targetMin + 1, Math.min(120, Math.round(max))),
          },
        }),
      });
    },
    reask(angle) {
      if (!active || active.kind !== "reader-questions") return;
      const pos = active.from;
      open("reader-questions", pos, {
        activity: activities.get(pos),
        reason: active.reason,
        saved: {
          id: active.savedId ?? "",
          kind: "reader-questions",
          name: "",
          config: { angle: angle.trim().slice(0, 200) },
          savedAt: 0,
        },
      });
    },
    anchorRect() {
      if (!active || editor.isDestroyed) return null;
      try {
        const from = active.sentenceFrom ?? active.from + 1;
        const start = editor.view.coordsAtPos(from);
        const dom = editor.view.nodeDOM(active.from);
        const block =
          dom instanceof HTMLElement ? dom.getBoundingClientRect() : null;
        return new DOMRect(
          block?.left ?? start.left,
          start.top,
          block?.width ?? 0,
          Math.max(0, (block?.bottom ?? start.bottom) - start.top),
        );
      } catch {
        return null;
      }
    },
    blockTop(pos) {
      if (editor.isDestroyed) return null;
      const dom = editor.view.nodeDOM(pos);
      return dom instanceof HTMLElement
        ? dom.getBoundingClientRect().top
        : null;
    },
    focusAnchor() {
      if (!active) return;
      editor
        .chain()
        .focus()
        .setTextSelection(active.sentenceFrom ?? active.from + 1)
        .scrollIntoView()
        .run();
    },
  };

  /* ── Settings and lifecycle ───────────────────────────────────── */

  const settings = async () => {
    const [live, inFlow] = await Promise.all([
      loadMetaFromIdb<boolean>("live-review-enabled"),
      loadMetaFromIdb<boolean>(IN_FLOW_SETTING_KEY),
    ]);
    if (stopped) return;
    enabled = live !== false && inFlow !== false;
    if (!enabled) {
      clearTimeout(pauseTimer);
      clearTimeout(stallTimer);
      setActive(null);
    }
  };
  const onOpen = (event: Event) => {
    const detail = (event as CustomEvent<{ kind: ToolKind; passage?: string }>)
      .detail;
    if (detail?.kind) controller?.openKind(detail.kind, detail.passage);
  };

  editor.on("transaction", onTransaction);
  window.addEventListener(IN_FLOW_SETTING_EVENT, settings);
  window.addEventListener("twyne:live-review-setting", settings);
  window.addEventListener(IN_FLOW_OPEN_EVENT, onOpen);
  void settings();
  publish({ active: null, ticks: [] });

  return () => {
    stopped = true;
    clearTimeout(pauseTimer);
    clearTimeout(stallTimer);
    clearTimeout(publishTimer);
    editor.off("transaction", onTransaction);
    window.removeEventListener(IN_FLOW_SETTING_EVENT, settings);
    window.removeEventListener("twyne:live-review-setting", settings);
    window.removeEventListener(IN_FLOW_OPEN_EVENT, onOpen);
    controller = null;
    publish({ active: null, ticks: [] });
  };
}
/**
 * Struggle signals — what the writer is wrestling with, read from how they
 * edit rather than from what they wrote.
 *
 * Everything here is local and pure. The tracker records counters per
 * paragraph as transactions land; nothing leaves the machine while the writer
 * types. On a pause the counters are committed into a version history and
 * scored, and only a paragraph that crosses the threshold is offered to the
 * classifier.
 *
 * The four readings map one-to-one onto the in-flow tools:
 *
 *   sentence-lab      the same sentence rewritten again and again
 *   rhythm-strip      sentences split and joined, a long paragraph churning
 *   claim-check       hedges put in and taken out — unsure how hard to claim
 *   reader-questions  a stall at the end of a paragraph after cutting
 */

export type ToolKind =
  | "sentence-lab"
  | "rhythm-strip"
  | "claim-check"
  | "reader-questions";

export const TOOL_KINDS: readonly ToolKind[] = [
  "sentence-lab",
  "rhythm-strip",
  "claim-check",
  "reader-questions",
];

export const TOOL_LABELS: Record<ToolKind, string> = {
  "sentence-lab": "Sentence Lab",
  "rhythm-strip": "Rhythm Strip",
  "claim-check": "Claim Check",
  "reader-questions": "Reader Questions",
};

/** Paragraph-local counters. Plain data so it can be cloned and tested. */
export interface BlockActivity {
  /** Text as of the last recorded edit. */
  text: string;
  /** Text as of the last committed pause; the baseline for the next commit. */
  committed: string;
  /** Committed versions, oldest first, capped at {@link MAX_VERSIONS}. */
  versions: string[];
  inserted: number;
  deleted: number;
  undos: number;
  /** Rewrite count keyed by sentence index; reset when the sentence count moves. */
  rewrites: Record<number, number>;
  /** Earlier wordings of each rewritten sentence, oldest first. */
  attempts: Record<number, string[]>;
  sentenceCountChanges: number;
  hedgeFlips: number;
  /** Length when tracking began, for churn against net growth. */
  startLength: number;
  firstAt: number;
  lastEditAt: number;
  /** Last time the paragraph grew by a meaningful amount. */
  lastGrowthAt: number;
  /** Set after a dismissal; no reading fires until it has passed. */
  cooldownUntil: number;
}

export interface StruggleReading {
  /** 0..1 — the strongest single signal. */
  score: number;
  /** Tool kinds whose rule fired, strongest first. */
  hints: Array<{ kind: ToolKind; strength: number; reason: string }>;
  /** When `sentence-lab` fired: which sentence, by index. */
  sentenceIndex?: number;
}

export const MAX_VERSIONS = 4;
const MAX_ATTEMPTS = 5;
export const STRUGGLE_THRESHOLD = 0.5;
/** Growth below this many characters does not count as progress. */
const GROWTH_CHARS = 12;
/** A stall is this long without growth, after the writer has been cutting. */
const STALL_MS = 40_000;

const HEDGE =
  /\b(perhaps|maybe|arguably|possibly|probably|somewhat|seems?|appears?|might|may|could|likely|suggests?|in some ways|to some extent|i think|i believe)\b/gi;

export function hedgeCount(text: string): number {
  return text.match(HEDGE)?.length ?? 0;
}

export interface SentenceSpan {
  text: string;
  /** Offsets into the paragraph text. */
  from: number;
  to: number;
}

/**
 * Sentence boundaries, deliberately simple: terminal punctuation followed by
 * whitespace. Abbreviations split wrongly now and then; the tools show the
 * writer's own words back to them, so a bad split is visible and harmless.
 */
export function splitSentences(text: string): SentenceSpan[] {
  const spans: SentenceSpan[] = [];
  const re = /[^.!?…]+(?:[.!?…]+["'”’)\]]*|$)/g;
  let match: RegExpExecArray | null;
  while ((match = re.exec(text))) {
    if (match[0].length === 0) {
      re.lastIndex++;
      continue;
    }
    const raw = match[0];
    const lead = raw.length - raw.trimStart().length;
    const trimmed = raw.trim();
    if (!trimmed) continue;
    const from = match.index + lead;
    spans.push({ text: trimmed, from, to: from + trimmed.length });
  }
  return spans;
}

export function wordCount(text: string): number {
  return text.split(/\s+/).filter(Boolean).length;
}

export function emptyActivity(text: string, now: number): BlockActivity {
  return {
    text,
    committed: text,
    versions: text.trim() ? [text] : [],
    inserted: 0,
    deleted: 0,
    undos: 0,
    rewrites: {},
    attempts: {},
    sentenceCountChanges: 0,
    hedgeFlips: 0,
    startLength: text.length,
    firstAt: now,
    lastEditAt: now,
    lastGrowthAt: now,
    cooldownUntil: 0,
  };
}

/**
 * Count one edit. Called per transaction for each touched paragraph, so it
 * must stay O(paragraph): a common prefix/suffix trim, no diff library.
 */
export function recordEdit(
  activity: BlockActivity,
  after: string,
  now: number,
  options: { undo?: boolean } = {},
): BlockActivity {
  const before = activity.text;
  if (before === after) return activity;
  let start = 0;
  const min = Math.min(before.length, after.length);
  while (start < min && before[start] === after[start]) start++;
  let end = 0;
  while (
    end < min - start &&
    before[before.length - 1 - end] === after[after.length - 1 - end]
  )
    end++;
  const removed = before.length - start - end;
  const added = after.length - start - end;
  const grew = after.length - activity.committed.length >= GROWTH_CHARS;
  return {
    ...activity,
    text: after,
    inserted: activity.inserted + added,
    deleted: activity.deleted + removed,
    undos: activity.undos + (options.undo ? 1 : 0),
    lastEditAt: now,
    lastGrowthAt: grew ? now : activity.lastGrowthAt,
  };
}

/**
 * Fold everything since the last pause into one version. This is where
 * sentence rewrites and hedge flips are counted — per pause, not per
 * keystroke, so typing a sentence out letter by letter is not "rewriting" it.
 */
export function commitVersion(activity: BlockActivity): BlockActivity {
  const previous = activity.committed;
  const current = activity.text;
  if (previous === current) return activity;

  const before = splitSentences(previous);
  const after = splitSentences(current);
  let { rewrites, attempts, sentenceCountChanges, hedgeFlips } = activity;

  if (before.length !== after.length) {
    // The indices no longer mean the same thing either way. But only an edit
    // with untouched text after it is a split or a join — starting a new
    // sentence at the end, or cutting the last one, is ordinary writing.
    if (sharedTail(previous, current) >= 3) sentenceCountChanges++;
    rewrites = {};
    attempts = {};
  } else {
    const changed = after
      .map((sentence, i) => (sentence.text !== before[i].text ? i : -1))
      .filter((i) => i >= 0);
    // Exactly one sentence reworded, and not merely extended at its end —
    // extending is writing forward, not wrestling with it.
    if (changed.length === 1) {
      const i = changed[0];
      const was = before[i].text;
      const now = after[i].text;
      const extended = now.startsWith(was.replace(/[.!?…]+$/, ""));
      if (!extended && was.length >= 12) {
        rewrites = { ...rewrites, [i]: (rewrites[i] ?? 0) + 1 };
        const prior = attempts[i] ?? [];
        attempts = {
          ...attempts,
          [i]: [...prior.filter((a) => a !== was), was].slice(-MAX_ATTEMPTS),
        };
      }
    }
  }

  if (hedgeCount(previous) !== hedgeCount(current)) hedgeFlips++;

  const versions = [...activity.versions, current].slice(-MAX_VERSIONS);
  return {
    ...activity,
    committed: current,
    versions,
    rewrites,
    attempts,
    sentenceCountChanges,
    hedgeFlips,
  };
}

/** Length of the common ending, ignoring trailing space and punctuation. */
function sharedTail(a: string, b: string): number {
  const x = a.replace(/[\s.!?…"'”’)\]]+$/, "");
  const y = b.replace(/[\s.!?…"'”’)\]]+$/, "");
  let n = 0;
  while (
    n < x.length &&
    n < y.length &&
    x[x.length - 1 - n] === y[y.length - 1 - n]
  )
    n++;
  return n;
}

/** Score a paragraph. Pure: `now` is passed in so tests can age a stall. */
export function readStruggle(
  activity: BlockActivity,
  now: number,
  context: { cursorAtEnd?: boolean } = {},
): StruggleReading {
  if (now < activity.cooldownUntil) return { score: 0, hints: [] };
  const hints: StruggleReading["hints"] = [];
  const text = activity.text;
  const sentences = splitSentences(text);
  const words = wordCount(text);

  let sentenceIndex: number | undefined;
  let most = 0;
  for (const [key, count] of Object.entries(activity.rewrites)) {
    if (count > most && Number(key) < sentences.length) {
      most = count;
      sentenceIndex = Number(key);
    }
  }
  if (most >= 3) {
    hints.push({
      kind: "sentence-lab",
      strength: Math.min(1, 0.6 + (most - 3) * 0.1),
      reason: `You've reworded one sentence ${most} times.`,
    });
  }

  const churn =
    (activity.inserted + activity.deleted) /
    Math.max(40, Math.abs(text.length - activity.startLength) + 40);
  if (
    sentences.length >= 3 &&
    (activity.sentenceCountChanges >= 2 || (churn >= 4 && words >= 80))
  ) {
    hints.push({
      kind: "rhythm-strip",
      strength: Math.min(
        0.9,
        0.5 +
          activity.sentenceCountChanges * 0.1 +
          Math.max(0, churn - 4) * 0.02,
      ),
      reason:
        activity.sentenceCountChanges >= 2
          ? "You've been splitting and joining sentences here."
          : "This paragraph keeps being reworked.",
    });
  }

  if (activity.hedgeFlips >= 2 && words >= 10) {
    hints.push({
      kind: "claim-check",
      strength: Math.min(0.9, 0.5 + (activity.hedgeFlips - 2) * 0.15),
      reason: "You've been adding and removing qualifiers.",
    });
  }

  if (
    context.cursorAtEnd &&
    words >= 25 &&
    activity.deleted >= 40 &&
    now - activity.lastGrowthAt >= STALL_MS &&
    now - activity.lastEditAt >= 8_000
  ) {
    hints.push({
      kind: "reader-questions",
      strength: 0.5,
      reason: "You've paused here after cutting.",
    });
  }

  hints.sort((a, b) => b.strength - a.strength);
  return {
    score: hints[0]?.strength ?? 0,
    hints,
    sentenceIndex,
  };
}

/** Quiet a paragraph after the writer dismisses its tool. */
export function coolDown(
  activity: BlockActivity,
  now: number,
  ms = 5 * 60_000,
): BlockActivity {
  return { ...activity, cooldownUntil: now + ms };
}

