export const DEFAULT_SLOTS = ["A source", "An example", "A number"];
export const DEFAULT_RHYTHM = { targetMin: 8, targetMax: 28 };
export const READER_QUESTION_BANK = [
  "What does this let me understand that I couldn't before?",
