  if (activities.size > MAX_TRACKED) {
    const oldest = [...activities.entries()]
      .sort((a, b) => a[1].lastEditAt - b[1].lastEditAt)
      .slice(0, activities.size - MAX_TRACKED);
    for (const [pos] of oldest) activities.delete(pos);
  }

