  said: [["remarked", "a passing observation"], ["replied", "an answer"], ["explained", "makes something clear"]],
  says: [["states", "more formal"], ["argues", "makes a case"]],
  shows: [["reveals", "brings something hidden to view"], ["demonstrates", "stronger evidence"]],
  show: [["reveal", "bring something hidden to view"], ["demonstrate", "stronger evidence"]],
  think: [["believe", "conviction"], ["suspect", "less certain"], ["consider", "weigh an idea"]],
  thought: [["believed", "conviction"], ["suspected", "less certain"]],
  walked: [["strolled", "unhurried"], ["strode", "purposeful"], ["wandered", "without a fixed route"]],
  looked: [["glanced", "briefly"], ["stared", "fixed attention"], ["watched", "continued attention"]],
  quiet: [["silent", "no sound"], ["still", "no movement"], ["hushed", "suppressed sound"]],
  loud: [["noisy", "many sounds"], ["deafening", "much stronger"]],
  clear: [["plain", "easy to understand"], ["explicit", "fully stated"]],
  difficult: [["hard", "plainer"], ["demanding", "requires effort"]],
  use: [["employ", "more formal"], ["apply", "put to a purpose"]],
  used: [["employed", "more formal"], ["applied", "put to a purpose"]],
  help: [["assist", "more formal"], ["support", "sustain or back"]],
  need: [["require", "more formal"], ["want", "desire, not necessity"]],
  change: [["alter", "modify"], ["transform", "much stronger"]],
  changed: [["altered", "modified"], ["transformed", "much stronger"]],
  strange: [["unusual", "less judgemental"], ["uncanny", "unsettling familiarity"]],
  beautiful: [["lovely", "more conversational"], ["striking", "catches attention"]],
  quickly: [["swiftly", "more literary"], ["hurriedly", "with haste"]],
  slowly: [["gradually", "over time"], ["unhurriedly", "without haste"]],
  however: [["still", "more conversational contrast"], ["nevertheless", "more formal contrast"]],
  perhaps: [["maybe", "more conversational uncertainty"]],
  begin: [["start", "plainer"]], began: [["started", "plainer"]],
  end: [["finish", "completion"], ["conclude", "more formal"]],
  remember: [["recall", "bring to mind"]],
  problem: [["difficulty", "an obstacle"], ["question", "something to resolve"]],
  result: [["outcome", "what followed"], ["consequence", "an effect"]],
  possible: [["feasible", "can be done"], ["conceivable", "can be imagined"]],
  seems: [["appears", "more formal uncertainty"]],
