import { component$, useSignal, useStore, useStyles$ } from "@qwik.dev/core";
import type { SentenceLabProps } from "./catalog";
import { inFlowController } from "../editor/extensions/struggle-tracker";
import { SpeechTransport } from "../ui/speech-transport";
import { completeSentence } from "../../utils/sentence-ledger";
import { localSentenceCandidates, sentenceCandidate, sentenceWordDiff, sentenceWords, wordAlternatives } from "../../utils/sentence-bench";
import styles from "./sentence-bench.css?inline";

export const SentenceBench = component$<{ props: SentenceLabProps; filling: boolean; toolId: string }>(({ props, filling, toolId }) => {
  useStyles$(styles);
  const working = useSignal(props.sentence);
  const tab = useSignal("rewrite");
  const state = useStore({ wordFrom: -1, wordTo: -1, compare: "", applying: false, message: "" });
  const candidates = props.candidates ?? [
    ...localSentenceCandidates(props.sentence),
    ...props.attempts.filter(completeSentence).map(text => sentenceCandidate(props.sentence, text, "yours", "Earlier wording")),
    ...props.variants.filter(completeSentence).map(text => sentenceCandidate(props.sentence, text, "text-model", "Model wording", "Meaning has not been checked.")),
  ];
  const words = sentenceWords(props.sentence);
  const alternatives = wordAlternatives(props.sentence, state.wordFrom, state.wordTo);
  const allWords = sentenceWords(props.context?.paragraph ?? props.sentence);
  const repeated = (word: string) => allWords.filter(w => w.word.toLocaleLowerCase() === word.toLocaleLowerCase()).length;
  const Diff = ({ text }: { text: string }) => <span class="sentence-bench-diff">{sentenceWordDiff(props.sentence, text).map((part, i) => part.kind === "removed" ? <del key={i}>{part.text}</del> : part.kind === "added" ? <ins key={i}>{part.text}</ins> : <span key={i}>{part.text}</span>)}</span>;
  return <div class="in-flow-body sentence-bench" data-sentence-bench={props.sentenceId ?? "selection"}>
    <nav aria-label="Sentence bench sections" class="sentence-bench-tabs">
      {[["rewrite", "Rewrite"], ["words", "Words"], ["place", "Place"], ["hear", "Hear"]].map(([id, label]) => <button type="button" key={id} aria-pressed={tab.value === id} class={tab.value === id ? "is-on" : ""} onClick$={() => { tab.value = id; inFlowController()?.previewVariant(null); }}>{label}</button>)}
    </nav>
    {props.stale && <p class="sentence-bench-notice" role="status">This sentence changed. Reopen the bench before using a wording or moving it.</p>}
    {tab.value === "rewrite" && <section aria-label="Complete sentence alternatives">
      <p class="in-flow-label">Complete wordings</p>
      <ol class="in-flow-list sentence-bench-candidates">
        {candidates.map(candidate => <li key={candidate.id}>
          <button type="button" class={["in-flow-choice", { "in-flow-choice--on": working.value === candidate.text }]} onClick$={() => { working.value = candidate.text; state.message = ""; }} onMouseEnter$={() => inFlowController()?.previewVariant(candidate.text)} onMouseLeave$={() => inFlowController()?.previewVariant(null)} onFocus$={() => inFlowController()?.previewVariant(candidate.text)} onBlur$={() => inFlowController()?.previewVariant(null)} aria-label={`Compare ${candidate.operation}: ${candidate.text}`}>
            <Diff text={candidate.text} />
            <span class="sentence-bench-facts"><span class="sentence-bench-chip">{candidate.source === "text-model" ? "text model" : candidate.source}</span><span>{candidate.operation}</span><span>{candidate.wordDelta > 0 ? "+" : ""}{candidate.wordDelta} words</span></span>
          </button>
          <p class="sentence-bench-note">{candidate.grammar === "checked" ? "Harper checked" : candidate.grammar === "pending" ? "Grammar check pending" : "Grammar check unavailable"}{candidate.meaning ? ` · ${candidate.meaning.model} meaning ${candidate.meaning.probability.toFixed(2)}` : " · meaning unverified"}</p>
          {candidate.caution && <p class="sentence-bench-note">{candidate.caution}</p>}
          <button type="button" class="sentence-bench-link" aria-pressed={state.compare === candidate.text} onClick$={() => { state.compare = state.compare === candidate.text ? "" : candidate.text; }}>Compare alongside</button>
        </li>)}
      </ol>
      {filling && <p class="sentence-bench-note" role="status">Checking complete alternatives…</p>}
      {!candidates.length && !filling && <p class="sentence-bench-note">No safe rule change for this sentence. Try a word below, move it, hear it, or edit a complete wording.</p>}
    </section>}
    {tab.value === "words" && <section aria-label="Word alternatives">
      <p class="in-flow-label">Choose a word</p>
      <p class="sentence-bench-word-line">{words.map(word => <span key={word.from}><button type="button" disabled={!word.available} aria-pressed={state.wordFrom === word.from} class={{ "is-repeated": repeated(word.word) > 1, "is-on": state.wordFrom === word.from }} title={word.available ? `${repeated(word.word)} use${repeated(word.word) === 1 ? "" : "s"} in this paragraph; show alternatives` : `${repeated(word.word)} use${repeated(word.word) === 1 ? "" : "s"}; no bundled alternatives`} onClick$={() => { state.wordFrom = word.from; state.wordTo = word.to; }}>{word.word}</button>{" "}</span>)}</p>
      <p class="sentence-bench-note">Underlined words repeat in this paragraph. The bundled thesaurus offers possible meanings; it does not rank fit.</p>
      <ol class="in-flow-list">{alternatives.map(choice => <li key={choice.replacement}><button type="button" class="in-flow-choice" onClick$={() => { working.value = choice.sentence; state.message = ""; }} onMouseEnter$={() => inFlowController()?.previewVariant(choice.sentence)} onMouseLeave$={() => inFlowController()?.previewVariant(null)}><Diff text={choice.sentence} /><span class="sentence-bench-facts"><span class="sentence-bench-chip">thesaurus</span><span>{choice.nuance}</span></span></button><p class="sentence-bench-note">May change meaning. Harper checks the full sentence before use.</p></li>)}</ol>
    </section>}
    {tab.value === "place" && <section aria-label="Sentence placement choices">
      <p class="in-flow-label">Read another position</p>
      <p class="sentence-bench-note">These are neighbouring slots, by rule. Their fit has not been judged.</p>
      <ol class="in-flow-list">{(props.placements ?? []).map(slot => <li key={slot.id} class="sentence-bench-slot"><p class="sentence-bench-context">{slot.before && <span>{slot.before}{" "}</span>}<strong>{props.sentence}</strong>{slot.after && <span>{" "}{slot.after}</span>}</p><p class="sentence-bench-note">{slot.reason}</p><button type="button" class="btn-paper in-flow-mini" disabled={props.stale} onClick$={() => { if (!inFlowController()?.moveSentence(slot.id)) state.message = "The paragraph changed. Reopen the bench to choose a position."; }}>Move here</button></li>)}</ol>
      {!props.placements?.length && <p class="sentence-bench-note">Add another complete sentence to compare positions.</p>}
    </section>}
    {tab.value === "hear" && <section aria-label="Hear the sentence in context"><p class="in-flow-label">Listen in context</p><p class="sentence-bench-note">Reads the preceding sentence, this wording, and the following sentence through your narration player. Local speech works when its voice is installed.</p><SpeechTransport id={`sentence-bench-${toolId}`} playLabel="Hear this wording in context" onPlay$={() => inFlowController()?.hearVariant(working.value)} /></section>}
    {state.compare && <section aria-label="Candidate comparison" class="sentence-bench-comparison"><p class="in-flow-label">Alongside</p><p><span class="sentence-bench-chip">original</span>{props.sentence}</p><p><span class="sentence-bench-chip">comparison</span><Diff text={state.compare} /></p></section>}
    <section class="sentence-bench-working" aria-label="Working sentence in context">
      <label class="in-flow-label" for={`sentence-bench-working-${toolId}`}>Working wording</label>
      {props.context?.before && <p class="sentence-bench-context">{props.context.before}</p>}
      <textarea id={`sentence-bench-working-${toolId}`} class="in-flow-textarea" rows={3} value={working.value} onInput$={(_, el) => { working.value = el.value; state.message = ""; }} />
      {props.context?.after && <p class="sentence-bench-context">{props.context.after}</p>}
      {working.value !== props.sentence && <p class="sentence-bench-preview"><Diff text={working.value} /></p>}
      <div class="in-flow-actions"><button type="button" class="btn-press" disabled={props.stale || state.applying || !completeSentence(working.value) || working.value === props.sentence} onClick$={async () => { state.applying = true; const used = await inFlowController()?.applyVariant(working.value.trim()); state.applying = false; if (!used) state.message = "The wording could not be used. Check the bench notice and try again."; }}>{state.applying ? "Checking…" : "Use this wording"}</button><button type="button" class="btn-paper in-flow-mini" disabled={working.value === props.sentence} onClick$={() => { working.value = props.sentence; inFlowController()?.previewVariant(null); }}>Keep original</button></div>
      <p class="sentence-bench-note">Use a complete sentence. Undo restores the wording or position.</p>
      {state.message && <p class="sentence-bench-notice" role="status">{state.message}</p>}
    </section>
  </div>;
});

