import { describe, expect, test } from "bun:test";
import { completeSentence, emptySentenceLedger, mapSentenceLedger, reconcileSentenceLedger, settleSentenceWording, sentenceSimilarity, type LedgerSpan } from "./sentence-ledger";
const span = (text: string, from = 1, blockFrom = 0): LedgerSpan => ({ text, from, to: from + text.length, blockFrom });
const start = (text: string) => reconcileSentenceLedger(emptySentenceLedger(), [span(text)], 0);

describe("settled sentence wordings", () => {
  test("requires punctuation, spelling proof, and leaving the sentence or five seconds", () => {
    const entry = start("The river carries the town's memory.").entries[0];
    expect(settleSentenceWording(entry, 1200, 5, true).wordings).toHaveLength(0);
    expect(settleSentenceWording(entry, 5000, 5, false).wordings).toHaveLength(0);
    expect(settleSentenceWording(entry, 5000, 5, true).wordings).toHaveLength(1);
    expect(settleSentenceWording(entry, 1200, 100, true).wordings).toHaveLength(1);
    expect(completeSentence("The river carr")).toBe(false);
    expect(settleSentenceWording({ ...entry, text: "The river carr" }, 5000, null, true).wordings).toHaveLength(0);
  });
  test("removes prefixes and collapses near spelling edits", () => {
    let entry = settleSentenceWording(start("The river carries.").entries[0], 5000, null, true);
    entry = settleSentenceWording({ ...entry, text: "The river carries the town's memory." }, 6000, null, true);
    expect(entry.wordings.map(w => w.text)).toEqual(["The river carries the town's memory."]);
    const edited = settleSentenceWording({ ...entry, text: "The river carried the town's memory." }, 7000, null, true);
    expect(edited.wordings).toHaveLength(1);
  });
});

describe("sentence identity and lineage", () => {
  test("preserves IDs and checked wordings when a sentence moves across paragraphs", () => {
    let ledger = start("The river carries the town's memory.");
    ledger.entries[0] = settleSentenceWording(ledger.entries[0], 5000, null, true);
    const id = ledger.entries[0].id;
    ledger = reconcileSentenceLedger(ledger, [span("The river carries the town's memory.", 80, 79)], 6000);
    expect(ledger.entries[0]).toMatchObject({ id, lineage: "move", retired: false });
    expect(ledger.entries[0].wordings).toHaveLength(1);
    expect(ledger.entries[0].placements).toHaveLength(2);
    // Undo returns the same identity, retaining the explicit placement history.
    ledger = reconcileSentenceLedger(ledger, [span("The river carries the town's memory.")], 7000);
    expect(ledger.entries[0].id).toBe(id);
    expect(ledger.entries[0].placements).toHaveLength(3);
  });
  test("a mapped shift from typing before a sentence is not a move", () => {
    let ledger = start("The river carries the town's memory.");
    ledger = mapSentenceLedger(ledger, p => p + 10, [{ from: 0, to: 0 }], 1000);
    ledger = reconcileSentenceLedger(ledger, [span("The river carries the town's memory.", 11, 10)], 2000);
    expect(ledger.entries[0].placements).toHaveLength(1);
    expect(ledger.entries[0].lineage).toBe("new");
  });
  test("cut then paste recovers the retired ID by exact text", () => {
    let ledger = start("The river carries the town's memory.");
    const id = ledger.entries[0].id;
    ledger = reconcileSentenceLedger(ledger, [], 1000);
    expect(ledger.entries[0].retired).toBe(true);
    ledger = reconcileSentenceLedger(ledger, [span("The river carries the town's memory.", 101, 100)], 2000);
    expect(ledger.entries[0]).toMatchObject({ id, retired: false, lineage: "move" });
  });
  test("split and join expose parent IDs instead of clearing history", () => {
    const text = "The river carried our memory; the bridge carried our hopes.";
    let ledger = start(text);
    ledger.entries[0] = settleSentenceWording(ledger.entries[0], 5000, null, true);
    const id = ledger.entries[0].id;
    ledger = reconcileSentenceLedger(ledger, [span("The river carried our memory."), span("The bridge carried our hopes.", 31)], 6000);
    const children = ledger.entries.filter(e => !e.retired);
    expect(children).toHaveLength(2);
    expect(children.some(e => e.id === id)).toBe(true);
    expect(children.every(e => e.lineage === "split")).toBe(true);
    expect(children.find(e => e.id !== id)?.parentIds).toContain(id);
    ledger = reconcileSentenceLedger(ledger, [span(text)], 7000);
    const joined = ledger.entries.find(e => !e.retired)!;
    expect(joined.lineage).toBe("join");
    expect(joined.parentIds.length).toBeGreaterThan(0);
    expect(joined.wordings.map(w => w.text)).toContain(text);
  });
  test("exact reservations prevent a changed sentence from stealing a neighbour ID", () => {
    let ledger = reconcileSentenceLedger(emptySentenceLedger(), [span("The river carried our memory."), span("The river carried our hopes.", 35)], 0);
    const neighbour = ledger.entries[1].id;
    ledger = reconcileSentenceLedger(ledger, [span("The river carries our memory."), span("The river carried our hopes.", 35)], 1000);
    expect(ledger.entries[1].id).toBe(neighbour);
    expect(sentenceSimilarity("A cold river.", "A cold river.")).toBe(1);
  });
});

import { describe, expect, test } from "bun:test";
import { checkSentenceCandidates, localSentenceCandidates, sentenceCandidate, sentencePlacementChoices, sentenceWordDiff, wordAlternatives } from "./sentence-bench";
import { completeSentence } from "./sentence-ledger";
import type { GrammarIssue } from "./grammar";
const issue = (problem: string): GrammarIssue => ({ id: problem, start: 0, end: problem.length, problem, kind: "Spelling", message: `Unknown word: ${problem}`, suggestions: [] });

describe("local sentence alternatives", () => {
  test("offline alternatives are complete, operation-labelled, and never claim verified meaning", () => {
    const original = "We made a decision to leave in order to find a very quiet room.";
    const candidates = localSentenceCandidates(original);
    expect(candidates.map(c => c.text)).toContain("We decided to leave in order to find a very quiet room.");
    expect(candidates.map(c => c.text)).toContain("We made a decision to leave to find a very quiet room.");
    expect(candidates.every(c => completeSentence(c.text) && c.source === "rule" && c.operation && !c.meaning)).toBe(true);
    expect(candidates.find(c => c.operation === "Reduce emphasis")?.caution).toContain("strength");
    expect(localSentenceCandidates("We made a decision to leav")).toEqual([]);
  });
  test("semicolon and trailing time clause transformations retain every clause", () => {
    expect(localSentenceCandidates("The tide carried our boats; the wind carried our voices.").map(c => c.text)).toContain("The tide carried our boats. The wind carried our voices.");
    expect(localSentenceCandidates("The tide carried our boats, after the storm had passed.").map(c => c.text)).toContain("After the storm had passed, the tide carried our boats.");
    expect(localSentenceCandidates("Mara found the map, after the storm had passed.").some(c => c.operation === "Front the time clause")).toBe(false);
  });
  test("Harper rejects new problems, including duplicate occurrences of an old problem", async () => {
    const original = "We walked to harbour.";
    const candidates = [sentenceCandidate(original, "We strolled to harbour.", "rule", "test"), sentenceCandidate(original, "We carr to harbour.", "rule", "test"), sentenceCandidate(original, "Harbour meets harbour.", "rule", "test")];
    const lint = async (s: string) => [...s.matchAll(/harbour|Harbour|carr/g)].map(m => issue(m[0].toLowerCase()));
    const checked = await checkSentenceCandidates(original, candidates, lint);
    expect(checked).toHaveLength(1);
    expect(checked[0].grammar).toBe("checked");
    expect(checked[0].text).toBe("We strolled to harbour.");
  });
  test("diff reconstructs both full wordings including punctuation and Unicode", () => {
    const before = "“Mara,” she said, “we really need that map.”";
    const after = "“Mara,” she replied, “we need the map.”";
    const diff = sentenceWordDiff(before, after);
    expect(diff.filter(p => p.kind !== "added").map(p => p.text).join("")).toBe(before);
    expect(diff.filter(p => p.kind !== "removed").map(p => p.text).join("")).toBe(after);
    expect(diff.some(p => p.kind === "removed" && p.text.includes("really"))).toBe(true);
  });
});
describe("word and placement alternatives", () => {
  test("word alternatives replace only the exact selected use and carry authored nuance", () => {
    const sentence = "She looked where he looked.";
    const choices = wordAlternatives(sentence, 4, 10);
    expect(choices.find(c => c.replacement === "glanced")?.sentence).toBe("She glanced where he looked.");
    expect(choices.every(c => c.source === "thesaurus" && c.nuance)).toBe(true);
    expect(wordAlternatives(sentence, 5, 10)).toEqual([]);
  });
  test("placements show complete context and omit opening a reference without a predecessor", () => {
    const paragraph = "The old map remained. This was our only clue. We followed the river.";
    const from = paragraph.indexOf("This"), to = from + "This was our only clue.".length;
    const choices = sentencePlacementChoices(paragraph, from, to);
    expect(choices).toHaveLength(1);
    expect(choices[0].paragraph).toBe("The old map remained. We followed the river. This was our only clue.");
    expect(choices[0].source).toBe("rule");
    expect(choices[0].reason).toContain("antecedent");
  });
});

