import { expect, spyOn, test } from "bun:test";
import { withEditor } from "../test-harness";
import { InFlowAnchor, inFlowController, inFlowSnapshot, startInFlowTools } from "./struggle-tracker";
import * as grammar from "../../../utils/grammar";
import * as idb from "../../../utils/idb";
import * as context from "../../../utils/model-context";
import * as judgement from "../../../utils/judgement-client";

const sentence = "We made a decision to leave in order to find a quiet room.";
const content = `<p>The map remained. <strong>${sentence}</strong> We followed the river.</p>`;
const pause = () => new Promise<void>(resolve => setTimeout(resolve, 30));
async function bench(run: Parameters<typeof withEditor>[1]) {
  const spies = [spyOn(grammar, "checkGrammar").mockResolvedValue([]), spyOn(idb, "loadAiSettingsFromIdb").mockResolvedValue(null), spyOn(idb, "loadMetaFromIdb").mockResolvedValue(false), spyOn(context, "loadModelBriefForFolio").mockResolvedValue(null), spyOn(judgement, "askJudgement").mockResolvedValue({ ok: false, transport: "none" })];
  try {
    await withEditor({ content, extensions: [InFlowAnchor] }, async harness => {
      const descriptor = Object.getOwnPropertyDescriptor(globalThis, "CustomEvent");
      Object.defineProperty(globalThis, "CustomEvent", { configurable: true, value: harness.dom.window.CustomEvent });
      const stop = startInFlowTools(harness.editor, { folioId: "sentence-fixture", brief: null, getClient: () => null });
      try { await pause(); inFlowController()!.openKind("sentence-lab", sentence); await pause(); await run?.(harness); }
      finally { stop(); await pause(); if (descriptor) Object.defineProperty(globalThis, "CustomEvent", descriptor); else Reflect.deleteProperty(globalThis, "CustomEvent"); }
    });
  } finally { spies.forEach(spy => spy.mockRestore()); }
}
test("complete offline candidates, in-manuscript ghost, checked rewrite and undo", async () => {
  await bench(async ({ editor }) => {
    const active = inFlowSnapshot().active!;
    expect(active.spec.elements.tool.type).toBe("SentenceLab");
    if (active.spec.elements.tool.type !== "SentenceLab") throw new Error("wrong tool");
    const candidate = active.spec.elements.tool.props.candidates!.find(c => c.operation === "Use a verb")!;
    expect(candidate.grammar).toBe("checked");
    inFlowController()!.previewVariant(candidate.text);
    await pause();
    expect(editor.view.dom.querySelector(".sentence-bench-ghost")?.textContent).toBe(` ${candidate.text}`);
    expect(await inFlowController()!.applyVariant(candidate.text)).toBe(true);
    expect(editor.getText()).toContain("We decided to leave");
    expect(editor.commands.undo()).toBe(true);
    expect(editor.getText()).toContain(sentence);
  });
});
test("placement preserves inline marks and is a single undo transaction", async () => {
  await bench(({ editor }) => {
    const element = inFlowSnapshot().active!.spec.elements.tool;
    if (element.type !== "SentenceLab") throw new Error("wrong tool");
    const slot = element.props.placements!.find(s => !s.before)!;
    expect(inFlowController()!.moveSentence(slot.id)).toBe(true);
    expect(editor.getText()).toBe(`${sentence} The map remained. We followed the river.`);
    expect(editor.getHTML()).toContain(`<strong>${sentence}</strong>`);
    expect(editor.commands.undo()).toBe(true);
    expect(editor.getHTML()).toBe(content);
  });
});
test("changed source refuses both wording and placement instead of matching another copy", async () => {
  await bench(async ({ editor }) => {
    const active = inFlowSnapshot().active!;
    const element = active.spec.elements.tool;
    if (element.type !== "SentenceLab") throw new Error("wrong tool");
    const slot = element.props.placements![0];
    editor.view.dispatch(editor.state.tr.insertText("new ", active.sentenceFrom));
    expect(await inFlowController()!.applyVariant("We decided to leave for a quiet room.")).toBe(false);
    expect(inFlowController()!.moveSentence(slot.id)).toBe(false);
    expect(editor.getText()).toContain(`new ${sentence}`);
  });
});
test("source edits during an asynchronous grammar check invalidate the pending apply", async () => {
  await bench(async ({ editor }) => {
    const active = inFlowSnapshot().active!;
    let release: (() => void) | undefined;
    const pending = new Promise<void>(resolve => { release = resolve; });
    const lint = spyOn(grammar, "checkGrammar").mockImplementation(async () => { await pending; return []; });
    try {
      const apply = inFlowController()!.applyVariant("We decided to leave for a quiet room.");
      editor.view.dispatch(editor.state.tr.insertText("new ", active.sentenceFrom));
      release!();
      expect(await apply).toBe(false);
      expect(editor.getText()).toContain(`new ${sentence}`);
    } finally { lint.mockRestore(); }
  });
});

