+import { completeSentence, sentenceSimilarity, type SentenceEntry } from "./sentence-ledger";
+import { splitSentences } from "./struggle-signals";
+
+export interface IndexedBlock { text: string; from: number; sectionId?: string; positionAt?: (offset: number) => number }
+export interface IndexedSpan { id: string; text: string; from: number; to: number; blockFrom: number; sectionId: string; ordinal: number }
+export interface SpanIndex { fingerprint: string; spans: IndexedSpan[]; limited: boolean }
+export function spanFingerprint(spans: Array<Pick<IndexedSpan, "id" | "text" | "from" | "to">>): string {
+  let hash = 2166136261;
+  for (const span of spans) for (const c of `${span.id}:${span.from}:${span.to}:${span.text}\n`) hash = Math.imul(hash ^ c.charCodeAt(0), 16777619);
+  return (hash >>> 0).toString(36);
+}
+/** Nodes always come from manuscript spans. IDs may reuse the sentence ledger. */
+export function buildSpanIndex(blocks: IndexedBlock[], ledger: SentenceEntry[] = [], limit = 2000): SpanIndex {
+  const spans: IndexedSpan[] = [];
+  let count = 0;
+  for (const block of blocks) {
+    for (const sentence of splitSentences(block.text)) {
+      if (!completeSentence(sentence.text)) continue;
+      count++;
+      if (spans.length >= limit) continue;
+      const from = block.positionAt?.(sentence.from) ?? block.from + 1 + sentence.from;
+      const to = block.positionAt?.(sentence.to) ?? block.from + 1 + sentence.to;
+      const entry = ledger.find(e => !e.retired && e.from === from && e.to === to && e.text === sentence.text);
+      spans.push({ id: entry?.id ?? `S${String(count).padStart(4, "0")}-${from}`, text: sentence.text, from, to, blockFrom: block.from, sectionId: block.sectionId ?? "section-1", ordinal: count });
+    }
+  }
+  return { spans, fingerprint: spanFingerprint(spans), limited: count > spans.length };
+}
+export function spanById(index: SpanIndex, id: string): IndexedSpan | null {
+  return index.spans.find(span => span.id === id) ?? null;
+}
+export type ThreadHypothesis = "exact-wording" | "word-overlap" | "reference";
+export interface ThreadPair { id: string; firstId: string; secondId: string; hypothesis: ThreadHypothesis; observation: string; overlap: number }
+const normalise = (text: string) => text.toLocaleLowerCase().replace(/[\p{P}\p{S}]/gu, "").replace(/\s+/g, " ").trim();
+const content = (text: string) => (text.toLocaleLowerCase().match(/\p{L}+/gu) ?? []).filter(w => !/^(?:a|an|the|and|or|but|of|to|in|on|for|with|is|are|was|were|it|this|that|we|i|he|she|they|as|by|be|had|has|have)$/.test(w));
+/** Candidate search is local lexical evidence, not semantic classification. */
+export function proposeThreadPairs(index: SpanIndex, focusId?: string, limit = 12): ThreadPair[] {
+  const out: ThreadPair[] = [], seen = new Set<string>();
+  const add = (first: IndexedSpan, second: IndexedSpan, hypothesis: ThreadHypothesis, observation: string, overlap: number) => {
+    const id = `${first.id}~${second.id}`;
+    if (seen.has(id)) return;
+    seen.add(id); out.push({ id, firstId: first.id, secondId: second.id, hypothesis, observation, overlap });
+  };
+  const focus = focusId ? spanById(index, focusId) : null;
