+      add(index.spans[i - 1], first, "reference", "Starts with a backward reference; check the preceding sentence as its antecedent.", 0);
+    }
+    // A focused request scans the piece against one sentence; an unscoped
+    // request stays inside a bounded section window, never all-pairs 2000².
+    const comparisons = focus ? first.id === focus.id ? [] : [focus] : index.spans.slice(i + 1, i + 65).filter(s => s.sectionId === first.sectionId);
+    for (const second of comparisons) {
+      const ordered = first.ordinal < second.ordinal ? [first, second] : [second, first];
+      if (normalise(first.text) === normalise(second.text)) add(ordered[0], ordered[1], "exact-wording", "The same wording occurs twice.", 1);
+      else if (content(first.text).length >= 4 && content(second.text).length >= 4) {
+        const overlap = sentenceSimilarity(content(first.text).join(" "), content(second.text).join(" "));
+        if (overlap >= .75) add(ordered[0], ordered[1], "word-overlap", `${Math.round(overlap * 100)}% content-word overlap; relation unverified.`, overlap);
+      }
