      const confirmed = !none && probability >= .6 && relation.confidence >= .5;
      return { ...pair, relation: relation.choice as ThreadRelation, exists: exists.noul, probability, source: "judgement", model: (response as { model?: string }).model ?? "judgement", state: none ? "no-relation" : confirmed ? "confirmed" : "candidate" };
    });
  } catch { return fallback; }
}

export const THREAD_INSTRUMENT_EVENT = "twyne:thread-instrument";
