export async function modelDownloadState(
  id: string,
  manifest: ModelFileManifest[],
): Promise<ModelDownloadState> {
  if (!canPersist()) {
    return {
      id,
      phase: "not-downloaded",
      downloadedBytes: 0,
      totalBytes: 0,
      progress: 0,
    };
  }
