import { expect, test, type Page, type TestInfo } from "@playwright/test";
import { writeFile } from "node:fs/promises";
import { INSTRUMENT_MANUSCRIPT, INSTRUMENT_REPEAT, INSTRUMENT_SENTENCE } from "./fixtures/instruments";

const manuscript = (page: Page) => page.locator(".ProseMirror").first();
const bench = (page: Page) => page.locator(".sentence-bench");
const threads = (page: Page) => page.getByRole("complementary", { name: "Threads", exact: true });
async function seed(page: Page) {
  await page.route(/\/api\/auth\//, route => route.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__instruments-seed", route => route.fulfill({ contentType: "text/html", body: "<!doctype html><title>Fictional instrument manuscript</title>" }));
  await page.goto("/__instruments-seed");
  await page.evaluate(async html => {
    const path = "/src/utils/idb.ts";
    const db = await import(/* @vite-ignore */ path);
    const now = Date.now(), id = "offline-instruments-fixture";
    await db.saveFoliosToIdb([{ id, name: "The map and the ledger", type: "draft", createdAt: now, updatedAt: now }]);
    await db.saveFolioContentToIdb(id, html);
    await db.saveActiveFolioIdToIdb(id);
    await db.saveMetaToIdb("live-review-enabled", false);
    await db.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  }, INSTRUMENT_MANUSCRIPT);
  await page.goto("/editor/");
  await expect(manuscript(page)).toContainText(INSTRUMENT_SENTENCE);
  await page.evaluate(() => document.fonts.ready);
}

/** Set up a native browser selection, then use only the visible action UI. */
async function selectPassage(page: Page, text: string) {
  await manuscript(page).evaluate((root, text) => {
    (root as HTMLElement).focus();
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes: Text[] = [];
    let plain = "", node: Node | null;
    while ((node = walker.nextNode())) { nodes.push(node as Text); plain += node.textContent ?? ""; }
    const start = plain.indexOf(text);
    if (start < 0) throw new Error(`Passage is absent: ${text}`);
    const range = document.createRange();
    let offset = 0, began = false;
    for (const node of nodes) {
      const end = offset + node.length;
      if (!began && start >= offset && start < end) { range.setStart(node, start - offset); began = true; }
      if (began && start + text.length <= end) { range.setEnd(node, start + text.length - offset); break; }
      offset = end;
    }
    const selection = window.getSelection()!;
    selection.removeAllRanges(); selection.addRange(range);
    root.dispatchEvent(new MouseEvent("mouseup", { bubbles: true }));
  }, text);
  await expect(page.getByRole("toolbar", { name: /^Actions for/ })).toBeVisible();
}
async function openBench(page: Page, text = INSTRUMENT_SENTENCE) {
  await selectPassage(page, text);
  await page.getByRole("button", { name: "Sentence bench", exact: true }).click();
  await expect(bench(page)).toBeVisible();
}
async function draftText(page: Page) {
  return manuscript(page).evaluate(root => {
    const copy = root.cloneNode(true) as HTMLElement;
    copy.querySelectorAll(".sentence-bench-ghost,.ld-ghost").forEach(n => n.remove());
    return copy.textContent;
  });
async function undo(page: Page) { await manuscript(page).locator("p").first().click(); await page.keyboard.press("ControlOrMeta+z"); }
async function capture(page: Page, info: TestInfo, name: string) {
  const path = info.outputPath(`${name}.png`);
  await page.screenshot({ path, animations: "disabled" });
  await info.attach(name, { path, contentType: "image/png" });
}

test("selection bench offers checked complete wordings, previews, applies and undoes offline", async ({ page }, info) => {
  const errors: string[] = [];
  page.on("pageerror", error => errors.push(error.message));
  await seed(page);
  const original = await draftText(page);
  await openBench(page);
  const candidate = bench(page).getByRole("button", { name: /^Compare Use a verb:/ });
  await expect(candidate).toBeVisible();
  await expect(bench(page)).toContainText("Harper checked");
  await candidate.hover();
  await expect(page.locator(".sentence-bench-ghost")).toContainText("We decided to leave");
  expect(await draftText(page)).toBe(original);
  await capture(page, info, "01-complete-wording-preview");
  await candidate.click();
  await expect(bench(page).locator("textarea")).toHaveValue("We decided to leave in order to find a very quiet room.");
  await bench(page).getByRole("button", { name: "Use this wording", exact: true }).click();
  await expect(manuscript(page)).toContainText("We decided to leave");
  await expect(bench(page)).toHaveCount(0);
  await capture(page, info, "02-wording-used");
  await undo(page);
  await expect.poll(() => draftText(page)).toBe(original);
  expect(errors).toEqual([]);
});

