.in-flow-connector {
  position: absolute;
  left: 100%;
  width: 28px;
  height: 0;
  border-top: 1px dashed
    color-mix(in srgb, var(--color-cobalt) 55%, transparent);
  pointer-events: none;
}
.in-flow-popover {
  position: fixed;
  z-index: var(--z-dropdown);
  max-height: calc(100dvh - 24px);
  overflow: auto;
}
.in-flow-card {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem 0.7rem;
  border: 1px solid var(--color-paper-3);
  border-left: 3px solid var(--color-cobalt);
  border-radius: 2px;
  background: var(--color-paper);
  color: var(--color-ink);
  font: 0.875rem/1.55 var(--font-serif);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 8px 24px -16px rgb(0 0 0 / 0.35);
}
.in-flow-card__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  position: absolute;
  right: -20px;
  width: 3px;
  height: 1.2em;
  border-radius: 1px;
  background: color-mix(in srgb, var(--color-cobalt) 45%, transparent);
}
.zen-mode .in-flow-rails {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .in-flow-rail,
  .in-flow-bar__fill {
    transition: none;
  }
}
@media print {
  .in-flow-rails,
  .in-flow-popover {
    display: none !important;
  }
  .twyne-in-flow-span,
  .twyne-in-flow-sentence {
    background: none !important;
  }
}

/* Rubric: the arithmetic behind the grade, only when asked for. */
.rubric-explainer__sum {
  width: 100%;
  border-collapse: collapse;

