@media print {
  .live-review-status,
  .twyne-quick-review-marker,
  .twyne-quick-review-card {
    display: none !important;
  }
}

/* ── In-flow tools: the margins ──────────────────────────────
 * Right margin holds the one live tool, level with its passage;
 * left margin holds the writer's kept tools and the working ticks.
 * Both scroll with the page because they live inside the canvas. */
.twyne-in-flow-span {
  background-image: linear-gradient(
    to top,
    color-mix(in srgb, var(--color-cobalt) 38%, transparent) 1px,
    transparent 1px
  );
  background-repeat: no-repeat;
  background-size: 100% 100%;
}
.twyne-in-flow-sentence {
  background-color: color-mix(in srgb, var(--color-cobalt) 14%, transparent);
  border-radius: 2px;
}
.in-flow-rails {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.in-flow-rails > * {
  pointer-events: auto;
}
.in-flow-rail {
  position: absolute;
  left: calc(100% + 28px);
  transition: top 180ms ease-out;
}
.in-flow-connector {
  position: absolute;
  left: 100%;
  width: 28px;
  height: 0;
  border-top: 1px dashed
    color-mix(in srgb, var(--color-cobalt) 55%, transparent);
  pointer-events: none;
}
.in-flow-popover {
  position: fixed;
  z-index: var(--z-dropdown);
  max-height: calc(100dvh - 24px);
  overflow: auto;
}
.in-flow-card {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.8rem 0.9rem 0.7rem;
  border: 1px solid var(--color-paper-3);
  border-left: 3px solid var(--color-cobalt);
  border-radius: 2px;
  background: var(--color-paper);
  color: var(--color-ink);
  font: 0.875rem/1.55 var(--font-serif);
  box-shadow:
    0 1px 0 var(--color-paper-3),
    0 8px 24px -16px rgb(0 0 0 / 0.35);
}
.in-flow-card__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: baseline;
  column-gap: 0.5rem;
}
.in-flow-card__title {

