import {
  component$,
  useStore,
  useStylesScoped$,
  $,
  type QRL,
} from "@qwik.dev/core";
import { useConvexClient } from "../../utils/convex-context";
import { useAuth } from "../../utils/auth-context";
import { askJudgement } from "../../utils/judgement-client";
import {
  systemOneWait,
  spendSystemOne,
  backOffSystemOne,
} from "../../utils/system-one-budget";
import {
  buildEntityInstrumentRequest,
  classifyEntityInstrument,
  type EntityInstrumentIndex,
  type EntityInstrumentResult,
  type EntityReadingKind,
  type EntityEvidence,
} from "../../utils/entity-instrument";
import styles from "./entity-instrument.css?inline";

export interface EntityInstrumentProps {
  index: EntityInstrumentIndex;
  contextKey: string;
  context?: string;
  /** Parent verifies exact current document text before jumping. */
  onJump$?: QRL<(span: EntityEvidence, indexKey: string) => void>;
}
export const EntityInstrument = component$<EntityInstrumentProps>((props) => {
  useStylesScoped$(styles);
  const client = useConvexClient(),
    auth = useAuth();
  const state = useStore<{
    selected: string;
    kind: EntityReadingKind;
    attribute: string;
    busy: boolean;
    notice: string;
    generation: number;
    account: string | null;
    result: EntityInstrumentResult | null;
  }>({
    selected: "",
    kind: "relationship",
    attribute: "",
    busy: false,
    notice: "",
    generation: 0,
    account: null,
    result: null,
  });
  const selectedId = props.index.candidates.some(
    (candidate) => candidate.id === state.selected,
  )
    ? state.selected
    : (props.index.candidates[0]?.id ?? "");
  const selected = props.index.candidates.find(
    (candidate) => candidate.id === selectedId,
  );
  let requestKey = "";
  try {
    requestKey = buildEntityInstrumentRequest(
      props.index,
      selectedId,
      state.kind,
      props.contextKey,
      props.context ?? "",
      state.attribute,
    ).key;
  } catch {
    /* Prerequisites appear alongside the input. */
  }
  const currentResult =
    state.result?.key === requestKey &&
    state.account === (auth.value.user?.id ?? null)
      ? state.result
      : null;
  const read = $(async () => {
    state.notice = "";
    if (systemOneWait() > 0) {
      state.notice =
        "The shared judgement budget is resting. Try again shortly.";
      return;
    }
    let request;
    try {
      request = buildEntityInstrumentRequest(
        props.index,
        selectedId,
        state.kind,
        props.contextKey,
        props.context ?? "",
        state.attribute,
      );
    } catch (error) {
      state.notice =
        error instanceof Error
          ? error.message
          : "Choose the source context first.";
      return;
    }
    if (!request.specs.length) {
      state.notice =
        "There are no eligible source pairs or dialogue spans for this reading. Try another entity or task.";
      return;
    }
    const generation = ++state.generation,
      account = auth.value.user?.id ?? null;
    const selection = selectedId,
      kind = state.kind,
      attribute = state.attribute,
      context = props.context ?? "";
    const current = () =>
      generation === state.generation &&
      account === (auth.value.user?.id ?? null) &&
      props.index.key === request.indexKey &&
      props.contextKey === request.contextKey &&
      (props.context ?? "") === context &&
      (state.selected || props.index.candidates[0]?.id) === selection &&
      state.kind === kind &&
      state.attribute === attribute;
    state.busy = true;
    spendSystemOne();
    const result = await classifyEntityInstrument(
      request,
      (input) => askJudgement(client.value, input),
      current,
    );
    if (current()) {
      state.result = result;
      state.account = account;
      state.notice = result
        ? request.excluded
          ? `${request.excluded} additional comparisons were outside this bounded reading.`
          : ""
        : "The selected judgement model could not return this reading. Source presence remains available locally.";
      if (!result) backOffSystemOne();
    }
    if (generation === state.generation) state.busy = false;
  });
  return (
    <section class="entity-instrument" aria-label="Entity instrument">
      <h2>Follow an entity through the piece</h2>
      <p>
        Name candidates and mentions come from code. They may include places or
        ordinary capitalised words; they are not confirmed characters.
      </p>
      {!selected ? (
        <p>No name candidates were found in the indexed passage.</p>
      ) : (
        <>
          <label>
            Entity candidate
            <select
              value={selectedId}
              onChange$={(_, el) => {
                state.selected = el.value;
                state.generation++;
                state.busy = false;
                state.result = null;
              }}
            >
              {props.index.candidates.map((candidate) => (
                <option key={candidate.id} value={candidate.id}>
                  {`${candidate.name} · ${candidate.mentions.length} mentions`}
                </option>
              ))}
            </select>
          </label>
          <h3>Presence · code</h3>
          <div class="entity-presence">
            {props.index.sections.map((section, at) => (
              <div key={section.index}>
                <span>{section.title}</span>
                <strong>{selected.counts[at] ?? 0}</strong>
              </div>
            ))}
          </div>
          {selected.variants.length > 0 && (
            <p>
              Spelling variants: {selected.variants.join(", ")}. Grouping is a
              spelling heuristic.
            </p>
          )}
          <details>
            <summary>Inspect source passages</summary>
            {props.index.evidence
              .filter(
                (span) =>
                  span.kind === "passage" &&
                  span.entityIds.includes(selectedId),
              )
              .map((span) => (
                <div key={span.id} class="entity-source">
                  <button
                    type="button"
                    disabled={!props.onJump$}
                    onClick$={() => props.onJump$?.(span, props.index.key)}
                  >
                    ¶{span.paragraph} · jump to exact source
                  </button>
                  <blockquote>{span.text}</blockquote>
                </div>
              ))}
          </details>
          <label>
            Reading
            <select
              value={state.kind}
              onChange$={(_, el) => {
                state.kind = el.value as EntityReadingKind;
                state.generation++;
                state.busy = false;
              }}
            >
              {["relationship", "continuity", "attribution"].map((kind) => (
                <option key={kind} value={kind}>
                  {kind === "relationship"
                    ? "Relationships by section"
                    : kind === "continuity"
                      ? "Attribute continuity"
                      : "Blind dialogue attribution"}
                </option>
              ))}
            </select>
          </label>
          {state.kind === "continuity" && (
            <label>
              Attribute to compare
              <input
                value={state.attribute}
                maxLength={200}
                placeholder="Age, eye colour, coat…"
                onInput$={(_, el) => {
                  state.attribute = el.value;
                  state.generation++;
                  state.busy = false;
                }}
              />
            </label>
          )}
          <p class="entity-note">
            {state.kind === "attribution"
              ? "Only the literal utterance and brief go to this blind reading; speaker tags are withheld. Unknown is a valid answer. This is a voice comparison, not a distinctness or accuracy grade."
              : state.kind === "continuity"
                ? "The model compares adjacent passages for the named attribute. A potential contradiction is a lead for you to inspect, not a verified factual error."
                : "Pairs must occur in the same paragraph. The model reads up to three exact passages per section; co-presence alone does not establish a relationship."}
          </p>
          <button
            type="button"
            disabled={state.busy || !requestKey}
            onClick$={read}
          >
            {state.busy
              ? "Reading selected evidence…"
              : "Read with judgement model"}
          </button>
          {currentResult?.readings.map((reading) => (
            <article class="entity-reading" key={reading.id}>
              <h3>{reading.choice}</h3>
              <p class="entity-note">
                {reading.model} · {Math.round(reading.probability * 100)}%
                distribution weight. Concentration is not correctness.
              </p>
              <p>
                {reading.entityIds
                  .map(
                    (id) =>
                      props.index.candidates.find(
                        (candidate) => candidate.id === id,
                      )?.name ?? "Unknown",
                  )
                  .join(" / ")}
              </p>
              <details>
                <summary>Full distribution and exact evidence</summary>
                {Object.entries(reading.probabilities).map(
                  ([label, probability]) => (
                    <div class="entity-probability" key={label}>
                      <span>{label}</span>
                      <span>{Math.round(probability * 100)}%</span>
                    </div>
                  ),
                )}
                {reading.evidenceIds.map((id) => {
                  const span = props.index.evidence.find(
                    (evidence) => evidence.id === id,
                  );
                  return span ? (
                    <div class="entity-source" key={id}>
                      <button
                        type="button"
                        disabled={!props.onJump$}
                        onClick$={() => props.onJump$?.(span, props.index.key)}
                      >
                        ¶{span.paragraph} · exact source
                      </button>
                      <blockquote>{span.text}</blockquote>
                    </div>
                  ) : null;
                })}
              </details>
            </article>
          ))}
        </>
      )}
      {props.index.limited && (
        <p role="status">
          The local index is bounded to 80 KB of text, 60 candidates and 240
          evidence spans. This is a partial view.
        </p>
      )}
      {state.notice && <p role="status">{state.notice}</p>}
    </section>
  );
});
import {
  component$,
  useStore,
  useSignal,
  useVisibleTask$,
  useStylesScoped$,
  $,
} from "@qwik.dev/core";
import {
  useAuth,
  hasAuthenticatedConvexIdentity,
} from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import {
  accountKnowledgeSnapshot,
  subscribeAccountKnowledge,
  refreshAccountKnowledge,
  accountResources,
  chooseAccountSource,
  type AccountKnowledgeSnapshot,
  type AccountResource,
} from "../../utils/account-knowledge";
import {
  instrumentTaskRefs,
  safeInstrumentTaskError,
} from "../../utils/instrument-tasks";
import {
  instrumentContextIsStale,
  instrumentTaskCanCancel,
  type InstrumentTaskKind,
  type InstrumentSourceRef,
  type InstrumentTaskView,
} from "../../utils/instrument-tasks-model";
import type { Id } from "../../../convex/_generated/dataModel";
import styles from "./task-desk.css?inline";
import { InstrumentIntentField } from "./instrument-intent-field";

export interface TaskDeskProps {
  folioId: string;
  selectedText?: string;
}
/** Mount inside the existing AuthProvider and ConvexProvider. */
export const TaskDesk = component$((props: TaskDeskProps) => {
  useStylesScoped$(styles);
  const auth = useAuth();
  const client = useConvexClient();
  const text = useSignal(props.selectedText ?? "");
  const instruction = useSignal(
    "Review this passage for clarity and identify the most useful next revision.",
  );
  const kind = useSignal<InstrumentTaskKind>("writing-review");
  const sourceId = useSignal("");
  const state = useStore<{
    tasks: InstrumentTaskView[];
    snapshot: AccountKnowledgeSnapshot;
    resources: AccountResource[];
    selected: InstrumentSourceRef[];
    busy: boolean;
    error: string;
    request: string;
    comments: Record<string, string>;
    alive: boolean;
    version: number;
  }>({
    tasks: [],
    snapshot: {
      account: null,
      sources: [],
      choices: {},
      loading: false,
      error: "",
    },
    resources: [],
    selected: [],
    busy: false,
    error: "",
    request: "",
    comments: {},
    alive: false,
    version: 0,
  });
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ track, cleanup }) => {
    const currentClient = track(() => client.value);
    const signedIn = track(() => hasAuthenticatedConvexIdentity(auth.value));
    const account = track(() => auth.value.user?.id);
    const folioId = track(() => props.folioId);
    const version = ++state.version;
    state.alive = true;
    state.tasks = [];
    state.selected = [];
    state.resources = [];
    state.comments = {};
    state.error = "";
    state.request = "";
    sourceId.value = "";
    const syncKnowledge = () => {
      if (!state.alive || state.version !== version) return;
      const next = accountKnowledgeSnapshot();
      if (state.snapshot.account !== next.account) {
        state.selected = [];
        state.resources = [];
        sourceId.value = "";
      }
      state.selected = state.selected.filter(
        (ref) =>
          next.choices[ref.sourceId]?.resources &&
          next.sources.some(
            (source) => source.id === ref.sourceId && source.resources_allowed,
          ),
      );
      state.snapshot = next;
    };
    syncKnowledge();
    const stopKnowledge = subscribeAccountKnowledge(syncKnowledge);
    const stopTasks =
      signedIn && currentClient && account
        ? currentClient.onUpdate(
            instrumentTaskRefs.list,
            { folioId },
            (rows) => {
              if (state.alive && state.version === version) state.tasks = rows;
            },
            (error) => {
              if (state.alive && state.version === version)
                state.error = safeInstrumentTaskError(error);
            },
          )
        : undefined;
    cleanup(() => {
      state.alive = false;
      stopKnowledge();
      stopTasks?.();
    });
  });
  const loadResources = $(async () => {
    const account = auth.value.user?.id;
    const source = sourceId.value;
    const version = state.version;
    state.busy = true;
    state.error = "";
    state.resources = [];
    try {
      const resources = await accountResources(source);
      if (
        state.alive &&
        state.version === version &&
        auth.value.user?.id === account &&
        sourceId.value === source
      )
        state.resources = resources;
    } catch {
      if (
        state.alive &&
        state.version === version &&
        auth.value.user?.id === account
      )
        state.error =
          "Enable resource access for this source in Account sources, then refresh and try again.";
    } finally {
      if (state.alive && state.version === version) state.busy = false;
    }
  });
  const queue = $(async () => {
    if (!client.value || !hasAuthenticatedConvexIdentity(auth.value)) return;
    const account = auth.value.user?.id;
    const version = state.version;
    state.busy = true;
    state.error = "";
    state.request ||= crypto.randomUUID();
    try {
      await client.value.mutation(instrumentTaskRefs.queue, {
        requestId: state.request,
        folioId: props.folioId,
        kind: kind.value,
        instruction: instruction.value,
        selectedText: text.value,
        sources: state.selected,
      });
      if (
        state.alive &&
        state.version === version &&
        auth.value.user?.id === account
      )
        state.request = "";
    } catch (error) {
      if (
        state.alive &&
        state.version === version &&
        auth.value.user?.id === account
      )
        state.error = safeInstrumentTaskError(error);
    } finally {
      if (state.alive && state.version === version) state.busy = false;
    }
  });
  const cancel = $(async (id: string) => {
    try {
      await client.value?.mutation(instrumentTaskRefs.cancel, {
        taskId: id as Id<"instrumentTasks">,
      });
    } catch (error) {
      state.error = safeInstrumentTaskError(error);
    }
  });
  const giveFeedback = $(
    async (id: string, verdict: "useful" | "not-useful") => {
      try {
        await client.value?.mutation(instrumentTaskRefs.feedback, {
          taskId: id as Id<"instrumentTasks">,
          verdict,
          comment: state.comments[id] ?? "",
        });
      } catch (error) {
        state.error = safeInstrumentTaskError(error);
      }
    },
  );
  const signedIn = hasAuthenticatedConvexIdentity(auth.value);
  return (
    <section class="task-desk" aria-label="Task desk">
      <header>
        <p class="dept-label">Writing instruments</p>
        <h2>Task desk</h2>
        <p>
          Choose a passage and a task. After your account accepts the queue
          request, work continues on the server and the result waits here when
          you return.
        </p>
      </header>
      {!signedIn && (
        <p class="task-notice">
          Sign in with Not Organic and sync this folio to queue durable tasks.
          Local browser work cannot continue after the tab closes.
        </p>
      )}
      <div class="task-form">
        <label>
          Task
          <select
            value={kind.value}
            onChange$={(_, el) => {
              kind.value = el.value as InstrumentTaskKind;
              state.request = "";
              instruction.value =
                kind.value === "source-research"
                  ? "Answer this passage's research question using the selected account resources. Identify missing evidence."
                  : "Review this passage for clarity and identify the most useful next revision.";
            }}
          >
            <option value="writing-review">Writing review</option>
            <option value="source-research">
              Research selected account resources
            </option>
          </select>
        </label>
        <label>
          Reference passage
          <textarea
            value={text.value}
            maxLength={20000}
            onInput$={(_, el) => {
              text.value = el.value;
              state.request = "";
            }}
          />
        </label>
        {props.selectedText && (
          <button
            type="button"
            onClick$={() => {
              text.value = props.selectedText ?? "";
              state.request = "";
            }}
          >
            Use current selected passage
          </button>
        )}
        <InstrumentIntentField
          value={instruction.value}
          contextKey={JSON.stringify([
            props.folioId,
            kind.value,
            text.value,
            state.selected,
          ])}
          label="What should this task do?"
          disabled={state.busy}
          onValue$={$((value) => {
            instruction.value = value;
            state.request = "";
          })}
        />
        <fieldset>
          <legend>Selected source scope</legend>
          <p class="task-small">
            Up to three resources shared with Twyne. Research uses these
            resources only. No web search or external tool calls are included.
          </p>
          <div class="task-actions">
            <button
              type="button"
              disabled={!signedIn || state.busy}
              onClick$={async () => {
                await refreshAccountKnowledge();
              }}
            >
              Refresh account sources
            </button>
            <a href="/settings">Manage account sources</a>
          </div>
          <label>
            Account source
            <select
              value={sourceId.value}
              onChange$={(_, el) => {
                sourceId.value = el.value;
                state.resources = [];
              }}
            >
              <option value="">Choose a resource-enabled source</option>
              {state.snapshot.sources
                .filter((source) => source.resources_allowed)
                .map((source) => (
                  <option key={source.id} value={source.id}>
                    {source.label}
                  </option>
                ))}
            </select>
          </label>
          {sourceId.value && (
            <label class="resource-choice">
              <input
                type="checkbox"
                checked={
                  state.snapshot.choices[sourceId.value]?.resources === true
                }
                disabled={state.busy}
                onChange$={(_, el) => {
                  chooseAccountSource(sourceId.value, "resources", el.checked);
                  state.resources = [];
                  state.request = "";
                }}
              />
              Enable resource reading from this source in Twyne
            </label>
          )}
          {state.snapshot.error && (
            <p role="status" class="task-notice">
              {state.snapshot.error}
            </p>
          )}
          {state.snapshot.loading && (
            <p role="status">Refreshing shared sources…</p>
          )}
          <button
            type="button"
            disabled={
              !sourceId.value ||
              !state.snapshot.choices[sourceId.value]?.resources ||
              state.busy
            }
            onClick$={loadResources}
          >
            List resources
          </button>
          {state.resources.map((resource) => (
            <label class="resource-choice" key={resource.uri}>
              <input
                type="checkbox"
                checked={state.selected.some(
                  (ref) =>
                    ref.sourceId === sourceId.value && ref.uri === resource.uri,
                )}
                disabled={state.busy}
                onChange$={(_, el) => {
                  const chosenSource = state.snapshot.sources.find(
                    (source) => source.id === sourceId.value,
                  );
                  if (!chosenSource) return;
                  const existing = state.selected.filter(
                    (ref) =>
                      ref.sourceId !== chosenSource.id ||
                      ref.uri !== resource.uri,
                  );
                  if (el.checked && existing.length >= 3) {
                    state.error = "Choose up to three resources.";
                    el.checked = false;
                    return;
                  }
                  state.selected = el.checked
                    ? [
                        ...existing,
                        {
                          sourceId: chosenSource.id,
                          uri: resource.uri,
                          label: (resource.title ?? resource.name).slice(
                            0,
                            200,
                          ),
                        },
                      ]
                    : existing;
                  state.request = "";
                }}
              />
              {resource.title ?? resource.name}
            </label>
          ))}
          {state.selected.length > 0 && (
            <ul>
              {state.selected.map((ref) => (
                <li key={`${ref.sourceId}:${ref.uri}`}>
                  {ref.label} <span class="task-small">({ref.sourceId})</span>{" "}
                  <code class="task-small">{ref.uri}</code>{" "}
                  <button
                    type="button"
                    onClick$={() => {
                      state.selected = state.selected.filter(
                        (selected) =>
                          selected.sourceId !== ref.sourceId ||
                          selected.uri !== ref.uri,
                      );
                      state.request = "";
                    }}
                  >
                    Remove
                  </button>
                </li>
              ))}
            </ul>
          )}
        </fieldset>
        <p class="task-small">
          Uses your hosted Not Organic model and account credit. Suggestions
          remain proposals for your review.
        </p>
        <button
          class="btn-press"
          type="button"
          disabled={
            !signedIn ||
            !client.value ||
            state.busy ||
            !text.value.trim() ||
            !instruction.value.trim() ||
            (kind.value === "source-research" && !state.selected.length)
          }
          onClick$={queue}
        >
          {state.busy ? "Working…" : "Queue task"}
        </button>
        {state.error && (
          <p role="alert" class="task-notice">
            {state.error}
          </p>
        )}
      </div>
      <div aria-live="polite" aria-relevant="additions text">
        {state.tasks.length === 0 && signedIn && (
          <p>No tasks queued for this folio.</p>
        )}
        {state.tasks.map((task) => (
          <article class="task-card" key={task._id}>
            <div class="task-meta">
              <h3>
                {task.kind === "source-research"
                  ? "Account source research"
                  : "Writing review"}
              </h3>
              <span class="task-status">
                {task.status === "failed" && task.failureKind === "needs-input"
                  ? "Needs your attention"
                  : task.status === "failed" &&
                      task.failureKind === "provider-unavailable"
                    ? "Provider unavailable"
                    : task.status}
              </span>
            </div>
            <p>{task.instruction}</p>
            {instrumentTaskCanCancel(task.status) && (
              <div class="task-actions">
                <button type="button" onClick$={() => cancel(task._id)}>
                  Cancel task
                </button>
                <span class="task-small">
                  Cancellation discards an in-flight result; an already sent
                  provider request may finish.
                </span>
              </div>
            )}
            {task.error && <p class="task-notice">{task.error}</p>}
            {instrumentContextIsStale(
              task,
              props.selectedText ?? text.value,
            ) && (
              <p class="task-small">
                This task refers to an earlier passage snapshot. Review its
                saved context before using the result.
              </p>
            )}
            <details>
              <summary>Exact task context and source scope</summary>
              <blockquote>{task.selectedText}</blockquote>
              <p class="task-small">Passage fingerprint: {task.fingerprint}</p>
              {task.sources.length ? (
                <ul>
                  {task.sources.map((ref) => (
                    <li key={`${ref.sourceId}:${ref.uri}`}>
                      {ref.label} — {ref.uri}
                    </li>
                  ))}
                </ul>
              ) : (
                <p>Passage only; no account resources selected.</p>
              )}
            </details>
            {task.result && (
              <>
                <div class="task-result">{task.result.text}</div>
                <p class="task-small">
                  {task.result.provider} · {task.result.model} ·{" "}
                  {new Date(task.result.completedAt).toLocaleString()}
                </p>
                {task.result.citations.map((ref, index) => (
                  <details key={`${ref.sourceId}:${ref.uri}`}>
                    <summary>
                      [{index + 1}] {ref.label}
                    </summary>
                    <p>{ref.uri}</p>
                    <blockquote>{ref.excerpt}</blockquote>
                    <p class="task-small">
                      Read {new Date(ref.retrievedAt).toLocaleString()} ·{" "}
                      {ref.fingerprint}
                    </p>
                  </details>
                ))}
                <label>
                  Feedback for this result
                  <textarea
                    value={
                      state.comments[task._id] ?? task.feedback?.comment ?? ""
                    }
                    maxLength={2000}
                    onInput$={(_, el) => {
                      state.comments[task._id] = el.value;
                    }}
                  />
                </label>
                <div class="task-actions">
                  <button
                    type="button"
                    aria-pressed={task.feedback?.verdict === "useful"}
                    onClick$={() => giveFeedback(task._id, "useful")}
                  >
                    Useful
                  </button>
                  <button
                    type="button"
                    aria-pressed={task.feedback?.verdict === "not-useful"}
                    onClick$={() => giveFeedback(task._id, "not-useful")}
                  >
                    Not useful
                  </button>
                  {task.feedback && (
                    <span class="task-small">
                      Feedback saved to your account.
                    </span>
                  )}
                </div>
              </>
            )}
          </article>
        ))}
      </div>
    </section>
  );
});

