              }}
            >
              {["relationship", "continuity", "attribution"].map((kind) => (
                <option key={kind} value={kind}>
                  {kind === "relationship"
                    ? "Relationships by section"
                    : kind === "continuity"
                      ? "Attribute continuity"
                      : "Blind dialogue attribution"}
                </option>
              ))}
            </select>
          </label>
          {state.kind === "continuity" && (
            <label>
