import { expect, test, type Page, type TestInfo } from "@playwright/test";
import { LOCAL_WRITING_PACKS } from "../src/utils/local-writing-manifest";

const FIRST = "Mara stood beside the window at dawn. The lamp flickered as Jules opened the door. A clock ticked in the quiet room.";
const SECOND = "Mara carried the ledger across the bridge. Jules waited below the arch and called her name.";
const HTML = `<h2>The waiting room</h2><p>${FIRST}</p><h2>Across the bridge</h2><p>${SECOND}</p>`;
const IDEA = "A brass lamp casts a narrow circle across the unopened ledger.";
const manuscript = (page: Page) => page.locator(".ProseMirror").first();
const dock = (page: Page) => page.getByRole("dialog", { name: "Writing instruments", exact: true });
const scene = (page: Page) => dock(page).locator(".scene-bench");

async function seed(page: Page) {
  await page.route(/\/api\/auth\//, route => route.fulfill({contentType:"application/json",body:"null"}));
  await page.route("**/__instrument-dock-seed", route => route.fulfill({contentType:"text/html",body:"<!doctype html><title>Fictional dock manuscript</title>"}));
  await page.goto("/__instrument-dock-seed");
  await page.evaluate(async html => {
    const path = "/src/utils/idb.ts";
    const db = await import(/* @vite-ignore */ path);
    const now = Date.now(), id = "offline-instrument-dock-fixture";
    await db.saveFoliosToIdb([{id,name:"The waiting room",type:"draft",createdAt:now,updatedAt:now}]);
    await db.saveFolioContentToIdb(id, html);
    await db.saveActiveFolioIdToIdb(id);
    await db.saveMetaToIdb("live-review-enabled",false);
    await db.saveMetaToIdb("signin-toast-dismissed",true);
    localStorage.setItem("living-desk-open","false");
    localStorage.setItem("twyne:editor:view:v1",JSON.stringify({zenMode:false,compositorOpen:false}));
  }, HTML);
  await page.goto("/editor/");
  await expect(manuscript(page)).toContainText(FIRST);
  await page.evaluate(() => document.fonts.ready);
}

/** Native selection is setup; all instrument interactions use visible controls. */
async function selectPassage(page: Page, text=FIRST) {
  await manuscript(page).evaluate((root,text) => {
    (root as HTMLElement).focus();
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT), nodes:Text[]=[];
    let plain="",node:Node|null;
    while((node=walker.nextNode())) { nodes.push(node as Text); plain+=node.textContent??""; }
    const start=plain.indexOf(text);
    if(start<0) throw new Error("Fixture passage is absent");
    const range=document.createRange(); let offset=0,began=false;
    for(const node of nodes) {
      const end=offset+node.length;
      if(!began && start>=offset && start<end) {range.setStart(node,start-offset); began=true;}
      if(began && start+text.length<=end) {range.setEnd(node,start+text.length-offset);break;}
      offset=end;
    }
    const selection=window.getSelection()!; selection.removeAllRanges(); selection.addRange(range);
    root.dispatchEvent(new MouseEvent("mouseup",{bubbles:true}));
  },text);
  await expect(page.getByRole("toolbar",{name:/^Actions for/})).toBeVisible();
}
async function openScene(page:Page,text=FIRST) {
  await selectPassage(page,text);
  await page.getByRole("toolbar",{name:/^Actions for/}).getByRole("button",{name:"Scene bench",exact:true}).click();
  await expect(dock(page)).toBeVisible();
  await expect(scene(page).getByRole("heading",{name:"Scene bench",exact:true})).toBeVisible();
}
async function capture(page:Page,info:TestInfo,name:string) {
  const path=info.outputPath(`${name}.png`);
  await page.screenshot({path,animations:"disabled"});
  await info.attach(name,{path,contentType:"image/png"});
}
async function close(page:Page) {
  await dock(page).getByRole("button",{name:"Close",exact:true}).click();
  await expect(dock(page)).not.toBeVisible();
}

// No model answers or provider responses are fabricated in these fixtures.
test("Scene selection inventories exact local source and jumps to that source",async({page},info)=>{
  await seed(page);
  const original=await manuscript(page).innerHTML();
  await openScene(page);
  await scene(page).getByText("Selected passage · 3 sentences",{exact:true}).click();
  await expect(scene(page).locator(".scene-bench__source blockquote")).toHaveText(FIRST);
  await expect(scene(page)).toContainText("Local English cue scan");
  const light=scene(page).locator('[data-scene-dimension="light"]');
  const evidence=light.locator("blockquote").first();
  await expect(evidence).toContainText("lamp flickered");
  const exact=await evidence.innerText();
  await scene(page).getByText("Ask for a model reading",{exact:true}).click();
  await expect(scene(page).getByRole("button",{name:"Read the scene with a model",exact:true})).toBeDisabled();
  await expect(scene(page).getByRole("button",{name:"Read scene aloud",exact:true})).toBeDisabled();
