async function selectPassage(page: Page, text=FIRST) {
  await manuscript(page).evaluate((root,text) => {
    (root as HTMLElement).focus();
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT), nodes:Text[]=[];
    let plain="",node:Node|null;
    while((node=walker.nextNode())) { nodes.push(node as Text); plain+=node.textContent??""; }
    const start=plain.indexOf(text);
    if(start<0) throw new Error("Fixture passage is absent");
    const range=document.createRange(); let offset=0,began=false;
    for(const node of nodes) {
      const end=offset+node.length;
      if(!began && start>=offset && start<end) {range.setStart(node,start-offset); began=true;}
      if(began && start+text.length<=end) {range.setEnd(node,start+text.length-offset);break;}
      offset=end;
    }
    const selection=window.getSelection()!; selection.removeAllRanges(); selection.addRange(range);
