    kind: EntityReadingKind;
    attribute: string;
    busy: boolean;
    notice: string;
    generation: number;
    account: string | null;
    result: EntityInstrumentResult | null;
  }>({
    selected: "",
    kind: "relationship",
    attribute: "",
    busy: false,
    notice: "",
    generation: 0,
    account: null,
    result: null,
  });
  const selectedId = props.index.candidates.some(
    (candidate) => candidate.id === state.selected,
  )
    ? state.selected
    : (props.index.candidates[0]?.id ?? "");
  const selected = props.index.candidates.find(
    (candidate) => candidate.id === selectedId,
  );
  let requestKey = "";
  try {
    requestKey = buildEntityInstrumentRequest(
      props.index,
      selectedId,
      state.kind,
      props.contextKey,
      props.context ?? "",
