  if (typeof value !== "string" || (!optional && !value.trim()))
    throw new Error(`${label} is missing.`);
  if (value.length > limit)
    throw new Error(`${label} is too long for this bounded room invitation (${limit} characters).`);
  return value;
}

/** Exact snapshot, including a changed proposal or question even if a caller reuses key. */
export function instrumentRoomContextKey(context: InstrumentRoomContext): string {
  return JSON.stringify([
    context.instrument, context.key, context.source, context.question,
    context.proposal ?? "", context.detail ?? "",
  ]);
}

/** No personaScope filter: comment-level editors remain eligible. Never silently omit a cast member. */
export function instrumentRoomCast(personas: readonly Persona[]): InstrumentRoomEditor[] {
  if (!personas.length) throw new Error("There are no editors in this room.");
  if (personas.length > INSTRUMENT_ROOM_LIMITS.cast)
    throw new Error(`This room invitation supports up to ${INSTRUMENT_ROOM_LIMITS.cast} editors; the current cast has ${personas.length}.`);
  const ids = new Set<string>();
  return personas.map((persona) => {
    const id = text(persona.id, "Editor identity", 200);
    if (ids.has(id)) throw new Error("The room has duplicate editor identities. Check the cast before inviting an editor.");
    ids.add(id);
    return {
      id,
      name: text(persona.name, "Editor name", 160),
      role: text(persona.role, "Editor role", 200),
      description: text(persona.description, "Editor description", 1_000, true),
