    instrument: context.instrument,
    key: text(context.key, "Passage identity", INSTRUMENT_ROOM_LIMITS.key),
    source: text(context.source, "Source passage", INSTRUMENT_ROOM_LIMITS.source),
    question: text(context.question, "Instrument question", INSTRUMENT_ROOM_LIMITS.question),
