      },
    },
  };
}

/** Validate the complete closed distribution at this boundary, even if a transport already checked it. */
export function readInstrumentRoomChoice(
  prepared: InstrumentRoomPrepared,
  response: JudgementResult,
): InstrumentRoomSelection {
  const base = { key: prepared.key, ...(response.model ? { model: response.model } : {}) };
  if (!response.ok)
    return { ...base, status: "unavailable", message: "The selected judgement model could not choose an editor. You can choose one yourself." };
  const raw = response.answers?.editor;
  const malformed = (): InstrumentRoomSelection => ({ ...base, status: "malformed", message: "The judgement model returned an invalid editor choice. No editor was invited." });
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return malformed();
  const answer = raw as Record<string, unknown>;
  const probabilities = answer.probabilities;
  if (
    answer.type !== "choice" || typeof answer.choice !== "string" ||
    !prepared.choices.includes(answer.choice) ||
    typeof answer.confidence !== "number" || !Number.isFinite(answer.confidence) ||
    answer.confidence < 0 || answer.confidence > 1 ||
    !probabilities || typeof probabilities !== "object" || Array.isArray(probabilities)
  ) return malformed();
  const values = probabilities as Record<string, unknown>;
  const keys = Object.keys(values);
  if (keys.length !== prepared.choices.length || keys.some((key) => !prepared.choices.includes(key))) return malformed();
  let sum = 0, maximum = -1;
  for (const key of prepared.choices) {
    const value = values[key];
    if (typeof value !== "number" || !Number.isFinite(value) || value < 0 || value > 1) return malformed();
    sum += value;
    maximum = Math.max(maximum, value);
  }
  if (Math.abs(sum - 1) > 0.01 || Math.abs((values[answer.choice] as number) - maximum) > 1e-6) return malformed();
