  return {
    ...base,
    status: answer.choice === INSTRUMENT_ROOM_NONE ? "none" : "selected",
    ...(selected ? { personaId: selected.id } : {}),
    confidence: answer.confidence,
    probabilities: Object.fromEntries(prepared.choices.map((key) => [key, values[key] as number])),
