  personaId: string | undefined,
  onAsk: (request: InstrumentRoomRequest) => InstrumentRoomResult | Promise<InstrumentRoomResult>,
  current: () => boolean | Promise<boolean> = () => true,
): Promise<InstrumentRoomResult> {
  if (!(await current())) return { ok: false, message: "The passage, room or settings changed. Invite an editor again." };
  const request = personaId ? instrumentRoomComment(prepared, personaId) : null;
  if (!request) return { ok: false, message: "No current editor was selected; no comment was requested." };
  try {
    return await onAsk(request);
  } catch {
    return { ok: false, message: "The editorial comment could not be requested. Try again from the current passage." };
  }
}
