    <ConvexProvider>
      <EntityInstrument
        index={index}
        contextKey="story-v1"
        context="Two travellers in a short story."
      />
    </ConvexProvider>
  );
});
export default {
  title: "Instruments/Entity instrument",
  component: Specimen,
  parameters: { layout: "padded" },
} satisfies Meta<typeof Specimen>;

