      };
    }
    results.push(row);
  }
  const dirtyStatus = git(["status", "--porcelain"]);
  const report = {
    schemaVersion: 1,
    mode: options.runModel ? "endpoint-model-routing" : "offline-corpus-validation",
    at: new Date().toISOString(),
    revision: git(["rev-parse", "HEAD"]), dirty: dirtyStatus === null ? null : !!dirtyStatus,
    corpusVersion: ROOM_ROUTING_CORPUS_VERSION,
    corpusSha256: sha(readFileSync(new URL("./room-routing-corpus.ts", import.meta.url), "utf8")),
    sourceSha256: Object.fromEntries(["evals/instruments/room-routing.ts", "src/utils/instrument-room.ts", "src/utils/personas.ts"].map((path) => [path, sha(readFileSync(resolve(REPO, path), "utf8"))])),
    canonicalCastSha256: sha(JSON.stringify(PERSONAS)),
    canonicalCast: PERSONAS.map(({ id, name, role }) => ({ id, name, role })),
    endpoint: options.runModel ? options.endpoint : null,
    requestedModel: options.runModel ? options.model : null,
    timeoutMs: options.timeoutMs, caseFilter: options.caseId ?? null,
    proof: options.runModel ? "Actual endpoint selection responses against authored acceptable choices; not persona contribution quality or live-account proof." : "Offline fixture/request validation only. Jev semantic quality, model distributions and latency were not measured.",
    limitations: ["Expectations are authored for fictional passages, not universal truth or a calibrated benchmark.", "No comment generation, writer-model endpoint or account-backed pathway is invoked by this runner."],
    results, flags,
    modelQuality: options.runModel ? (flags.length ? "authored-reference-flags" : "within-authored-acceptable-sets") : "not-run",
    reproduction: {
      command: `bun evals/instruments/room-routing.ts${options.runModel ? " --run-model --endpoint <chosen-endpoint> --model <chosen-model>" : ""}${options.caseId ? ` --case ${options.caseId}` : ""}`,
