  try {
    const options = parseRoomRoutingOptions(process.argv.slice(2));
    if (options.help) console.log("Usage: bun evals/instruments/room-routing.ts [--case exact-id] [--output directory]\nOptional explicit model run: --run-model --endpoint http(s)://host [--model name] [--timeout-ms 1000..120000]\nEndpoint may use TWYNE_ROOM_ROUTING_ENDPOINT. Credentials only TWYNE_ROOM_ROUTING_API_KEY. Default is offline corpus validation; no network calls.");
    else {
      const report = await runRoomRouting(options);
      if (report.flags.length) process.exitCode = 1;
